UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6d2779e1-252c-417d-a429-8c6f28d70d4b-en-535","language":"English","title":"Anandaram Dhekial Phukan","topic_slug":"anandaram-dhekial-phukan","definition":"Historical Context & The Language Crisis: Following the British annexation of Assam (Treaty of Yandaboo, 1826), the colonial administration imposed Bengali as the official language of courts and schools in 1836 under the erroneous assumption that Assamese was merely a vulgar dialect of Bengali. Anandaram Dhekial Phukan emerged as the pioneer intellectual who spearheaded the resistance against this linguistic subjugation. Literary Works & Textbooks: Asamiya Lorar Mitra (The Assamese Boy’s Companion, 1849): Written to provide native vernacular reading material for young students, fulfilling the colonial requirement of having standardized local textbooks before Assamese could be reinstated in classrooms.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6d2779e1-252c-417d-a429-8c6f28d70d4b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'anandaram-dhekial-phukan' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6d2779e1-252c-417d-a429-8c6f28d70d4b-en-536","language":"English","title":"Lakshminath Bezbaruah","topic_slug":"lakshminath-bezbaruah","definition":"The Jonaki Era & The Romantic Awakening: In 1889, along with Chandra Kumar Agarwala and Hemchandra Goswami, Bezbaruah founded the literary journal Jonaki under the aegis of the Asamiya Bhasa Unnati Sadhini Sabha (ABUSS) in Calcutta. This marked the advent of Romanticism (Romantisiwad) in Assamese literature, breaking away from medieval devotional models to embrace individual emotion, patriotism, and folklore. The Rasaraj Identity & Satirical Persona: Honored with the epithet \"Rasaraj\" (The King of Humor) by the Asom Sahitya Sabha in 1931 for his masterly use of humor and wit to provoke social reform. Adopted the pseudonym \"Kripabar Barbarua\" to author satirical essays including Kripabar Barbaruar Kakator Topola and Kripabar Barbaruar Obhotoni. Through Kripabar’s eccentric musings, Bezbaruah ridiculed Assamese inertia, blind imitation of Western manners, and orthodox social taboos.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6d2779e1-252c-417d-a429-8c6f28d70d4b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'lakshminath-bezbaruah' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6d2779e1-252c-417d-a429-8c6f28d70d4b-en-537","language":"English","title":"Dr. Banikanta Kakati","topic_slug":"dr-banikanta-kakati","definition":"Scientific Philology & Doctoral Dissertation: Submitted his doctoral thesis to Calcutta University in 1935, subsequently published as Assamese: Its Formation and Development (1941). Using comparative Indo-Aryan philology, Kakati documented Assamese as an independent language with a historical development distinct from Bengali, tracing it to Eastern Indo-Aryan sources. Key Published Books: Assamese: Its Formation and Development (Linguistic treatise). Purani Asamiya Sahitya (1940): Pioneered modern literary criticism, evaluating pre-colonial Vaishnava texts with aesthetic standards rather than blind devotion. The Mother Goddess Kamakhya (1948): An anthropological study detailing the fusion of Aryan and non-Aryan/Austric/Tibeto-Burman religious cults in Assam. Kalita Jatir Itibritta: An ethnological investigation into the social origins and mobility of the Kalita community in the Brahmaputra Valley. Sahitya Aru Prem: A philosophical critique of romantic love and ethical aestheticism in world literature.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6d2779e1-252c-417d-a429-8c6f28d70d4b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'dr-banikanta-kakati' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6d2779e1-252c-417d-a429-8c6f28d70d4b-en-538","language":"English","title":"Jyoti Prasad Agarwala","topic_slug":"jyoti-prasad-agarwala","definition":"The Title ''Rupkonwar'' & Philosophy of Sundarar Pujari: Conferred the title \"Rupkonwar\" (Prince of Beauty) by contemporary cultural circles and literary figures in recognition of his artistic pursuit of ideal beauty. As the \"Sundarar Pujari\" (Worshipper of Beauty), he defined beauty not as escapism, but as a revolutionary force (Biplobi Saundaryabodh) capable of demolishing social injustice, inequality, and colonial oppression. Pioneering Dramatic Literature: Sonit Konwari (1925): Modernized mythological theatre by integrating traditional folk rhythms with structured dialogue. Karengar Ligiri (The Maid of the Palace, 1930): A tragedy exploring individual psychological freedom against feudal societal conventions. Rupalim (1938): Set against a tribal backdrop, analyzing love, political tyranny, and moral sacrifice. Labhita (1948): A realistic drama capturing the transformation of a rural Assamese village girl into a political activist during the 1942 Quit India Movement and the INA campaign.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6d2779e1-252c-417d-a429-8c6f28d70d4b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'jyoti-prasad-agarwala' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6d2779e1-252c-417d-a429-8c6f28d70d4b-en-539","language":"English","title":"Bishnu Prasad Rabha","topic_slug":"bishnu-prasad-rabha","definition":"The Title ''Kalaguru'': The title \"Kalaguru\" (Master of Arts) was conferred on him by Dr. Sarvepalli Radhakrishnan at Banaras Hindu University following Rabha''s classical performance of the Nataraja Tandava dance. Cultural Synthesis & Tribal Integration: Rejected narrow chauvinism, asserting that Greater Assamese culture (Bor Asom) is fundamentally an amalgamation of diverse tribal streams (Bodo, Kachari, Mishing, Karbi, Rabha) and Sanskritic heritage. Documented indigenous musical scales, dances, and folklore in seminal works such as Asamiya Kristir Chamu Abhas (A Brief Overview of Assamese Culture). Revolutionary Politics: An active member of the Revolutionary Communist Party of India (RCPI), he went underground in the late 1940s, mobilizing peasant movements (Kisan Sabha) across lower Assam to resist feudal land systems. Imprisoned repeatedly, he utilized his creative arts as instruments of proletarian class struggle and tribal emancipation.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6d2779e1-252c-417d-a429-8c6f28d70d4b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'bishnu-prasad-rabha' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6d2779e1-252c-417d-a429-8c6f28d70d4b-en-540","language":"English","title":"Dr. Bhupen Hazarika","topic_slug":"dr-bhupen-hazarika","definition":"Lyrical Themes & Universal Humanism: Integrated the philosophies of Paul Robeson, folk realism, and humanitarian socialism into Assamese mass music. Landmark compositions: Bistirno Parore (an adaptation of Robeson''s Ol'' Man River, castigating the moral silence of the Brahmaputra), Manuhe Manuhor Babe (championing universal empathy), and Dola He Dola (depicting the suffering of palanquin bearers). Bridge of Ethnic Unity in the Northeast: Used his compositions to celebrate the folk traditions of the hills and plains, writing songs dedicated to the Khasi, Garo, Naga, Arunachal, and Mishing communities, serving as an emotional bridge during periods of regional ethnic friction. Chronology of National Awards & Honors: Padma Shri (1977). Sangeet Natak Akademi Award (1987). Dadasaheb Phalke Award (1992): India''s highest award in cinema, acknowledging his contribution to Assamese and Indian music/films. Padma Bhushan (2001). Asam Ratna (2009). Padma Vibhushan (2012, posthumously). Bharat Ratna (2019, posthumously): India''s highest civilian honor.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6d2779e1-252c-417d-a429-8c6f28d70d4b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'dr-bhupen-hazarika' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-c4e76bc8-9bd1-4b0f-9ddf-1d9c7a97b9ee-en-541","language":"English","title":"Assam Association","topic_slug":"assam-association","definition":"Genesis & Organizational Structure: Formed in 1903 through the initiative of middle-class intellectuals' || char(59) || ' held its inaugural annual conference at Dibrugarh in 1905. Raja Prabhat Chandra Baruah of Gauripur served as its first President' || char(59) || ' Manik Chandra Baruah served as its first General Secretary. Aims & Political Methods: Operated as the pioneer provincial political platform representing the interests of the people of Assam before the British Raj prior to the institutional spread of the Indian National Congress. Followed constitutional and moderate methods: submitting petitions, drafting memoranda, and seeking reform through regional legislative councils. Key Interventions & Achievements: Opposed the colonial administration''s heavy taxation on peasant land. Campaigned persistently against the British government''s lucrative excise policy that promoted the open sale and spread of opium (Kani). Protested the 1905 Partition of Bengal, resisting the incorporation of Assam into the newly created province of ''Eastern Bengal and Assam''.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = 'c4e76bc8-9bd1-4b0f-9ddf-1d9c7a97b9ee' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'assam-association' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-c4e76bc8-9bd1-4b0f-9ddf-1d9c7a97b9ee-en-542","language":"English","title":"Asom Chatra Sanmilan","topic_slug":"asom-chatra-sanmilan","definition":"Founding Conference: Established at its first annual session held in Guwahati in December 1916. The historic inaugural session was presided over by Lakshminath Bezbaruah. Official Mouthpiece (Milan): Launched the literary journal Milan in 1923, edited by leaders like Chandranath Sarmah and Sonaram Choudhury. The magazine served as an intellectual medium for Assamese poetry, essays, historical inquiry, and political commentary. Role in Language & Literature: Mandated the systematic preservation of Assamese linguistic identity, documenting oral folk vocabulary and supporting young authors. Demanded the introduction of Assamese as the medium of instruction at secondary and university levels across the province. Political engagement grew in the context of the national movement after the Jallianwala Bagh massacre (1919) and the Non-Cooperation Movement (1920–21). The Sanmilan continued its cultural and educational work as student participation in public life widened.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = 'c4e76bc8-9bd1-4b0f-9ddf-1d9c7a97b9ee' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'asom-chatra-sanmilan' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-c4e76bc8-9bd1-4b0f-9ddf-1d9c7a97b9ee-en-543","language":"English","title":"Tarun Ram Phukan","topic_slug":"tarun-ram-phukan","definition":"Title & Leadership: Popularly revered as \"Deshbhakta\" (Patriot of the Nation)' || char(59) || ' his death anniversary on July 28 is observed as Deshbhakta Divas in Assam. Renounced a lucrative legal practice as a Barrister to lead the Non-Cooperation Movement (1921) in Assam following Mahatma Gandhi''s tour of the province. Key Political Roles: Served as President of the Assam Provincial Congress Committee (APCC). 41st Pandu Congress Session (1926): As the Chairman of the Reception Committee, Phukan was instrumental in hosting the 41st session of the Indian National Congress at Pandu (Guwahati) in 1926. This successfully integrated Assam''s regional concerns into the pan-Indian national consciousness. Swarajist Politics: Sided with Motilal Nehru and Chittaranjan Das to join the Swaraj Party within the central legislative apparatus, advocating obstructionist tactics from inside the councils. Oratory & Literary Output: An orator who published literary and reflective essays, including Mor Sikhar Katha and works on hunting and wildlife preservation.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = 'c4e76bc8-9bd1-4b0f-9ddf-1d9c7a97b9ee' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'tarun-ram-phukan' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-c4e76bc8-9bd1-4b0f-9ddf-1d9c7a97b9ee-en-544","language":"English","title":"Gopinath Bardoloi","topic_slug":"gopinath-bardoloi","definition":"Premier & Architect of Modern Assam: Revered as \"Lokpriya\"' || char(59) || ' served as the first Chief Minister (then styled \"Premier\") of Assam (1938–39 and 1946–50). Awarded the Bharat Ratna posthumously in 1999, becoming the first Assamese recipient of India''s highest civilian decoration. Resistance Against the Cabinet Mission''s Grouping Scheme (1946): The Cabinet Mission Plan of 1946 placed Assam in Section C with Bengal, a proposal Assam’s representatives opposed because it could constrain the province’s political autonomy. Bardoloi and other Assamese leaders challenged the proposed grouping. Its interpretation was contested, and Assam did not remain in Section C. Institutional Legacy: Gauhati University (1948): Spearheaded the creation of the first university in Northeast India. Assam Medical College, Dibrugarh (1947): Converted the Berry White Medical School into a full medical college. Gauhati High Court (1948): Secured judicial autonomy for the state. Assam Agricultural College and the regional veterinary college networks.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = 'c4e76bc8-9bd1-4b0f-9ddf-1d9c7a97b9ee' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'gopinath-bardoloi' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-c4e76bc8-9bd1-4b0f-9ddf-1d9c7a97b9ee-en-545","language":"English","title":"Kalicharan Brahma","topic_slug":"kalicharan-brahma","definition":"Biographical Origin: Born Kalicharan Mech in 1860 at Kajigaon in the Goalpara/Kokrajhar region' || char(59) || ' later adopted the title Brahma upon his religious conversion. Brahma Dharma & Societal Regeneration: Initiated into the Vedic monotheistic Brahma faith by Swami Sibanarayan Paramhansa in Calcutta in 1906. Established the Brahma Dharma movement among the Bodo community to dismantle deep-rooted social vulnerabilities. Prohibited the traditional ritual sacrifice of animals and the consumption of rice-beer (Zou), which had historically driven Bodo families into severe debt to moneylenders. Promoted the sacred Yajna (fire ritual) accompanied by the Gayatri Mantra, cultivating self-respect and cultural dignity within the community. Educational & Economic Reform: Established middle schools, carpentry training workshops, and weaving centers across lower Assam to encourage vocational self-reliance. Promoted female literacy and abolished oppressive bridal price traditions.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = 'c4e76bc8-9bd1-4b0f-9ddf-1d9c7a97b9ee' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'kalicharan-brahma' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-c4e76bc8-9bd1-4b0f-9ddf-1d9c7a97b9ee-en-546","language":"English","title":"Bhimbar Deori","topic_slug":"bhimbar-deori","definition":"Establishment of the Assam Tribal League (1933): Co-founded the Assam Plains Tribal League in 1933, serving as its General Secretary. Unified diverse plains tribes (Deoris, Misings, Bodos, Sonowal Kacharis, Rabhas, Tiwas) into an autonomous political collective to negotiate with colonial and provincial authorities. The Line System & Protection of Tribal Lands: Campaigned against the settlement of immigrant peasants from East Bengal on indigenous ancestral territories. Led mass resistance demanding the strict enforcement and statutory strengthening of the colonial Line System, which evolved into the post-independence framework of Tribal Belts and Blocks in Assam to legally preserve tribal lands. The Bordoloi-Deori Pact (1940): Formulated an electoral and policy alliance between the Tribal League and Gopinath Bardoloi''s Congress coalition.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = 'c4e76bc8-9bd1-4b0f-9ddf-1d9c7a97b9ee' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'bhimbar-deori' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
