UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-c1b743e4-1ed4-4e7d-aaed-1c72b25a7128-en-548","language":"English","title":"Asom Chatra Sanmilan","topic_slug":"asom-chatra-sanmilan","definition":"Founding Conference: Established at its first annual session held in Guwahati in December 1916. The historic inaugural session was presided over by Lakshminath Bezbaruah. Official Mouthpiece (Milan): Launched the literary journal Milan in 1923, edited by leaders like Chandranath Sarmah and Sonaram Choudhury. The magazine served as an intellectual medium for Assamese poetry, essays, historical inquiry, and political commentary. Role in Language & Literature: Mandated the systematic preservation of Assamese linguistic identity, documenting oral folk vocabulary and supporting young authors. Demanded the introduction of Assamese as the medium of instruction at secondary and university levels across the province. Evolution into Political Activism: Initially formed as a strictly non-political, socio-cultural body focused on literary awakening and moral discipline among the youth. Under the leadership of Chandranath Sarmah and Hemchandra Baruah, the student body radicalized in response to the Jallianwala Bagh massacre (1919) and the Non-Cooperation call (1920–21).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = 'c1b743e4-1ed4-4e7d-aaed-1c72b25a7128' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'asom-chatra-sanmilan' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
