UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-c1b743e4-1ed4-4e7d-aaed-1c72b25a7128-en-550","language":"English","title":"Gopinath Bardoloi","topic_slug":"gopinath-bardoloi","definition":"Premier & Architect of Modern Assam: Revered as \"Lokpriya\"' || char(59) || ' served as the first Chief Minister (then styled \"Premier\") of Assam (1938–39 and 1946–50). Awarded the Bharat Ratna posthumously in 1999, becoming the first Assamese recipient of India''s highest civilian decoration. Resistance Against the Cabinet Mission''s Grouping Scheme (1946): Under the Cabinet Mission Plan of 1946, British India was divided into sections' || char(59) || ' Assam was placed in Section C alongside Muslim-majority Bengal. This grouping threatened Assam''s distinct political position and led its leaders to resist being bound to decisions made jointly with Bengal. Bardoloi mounted defiance against both the British authorities and the central Congress high command (including Jawaharlal Nehru, who initially hesitated). Assam''s representatives opposed automatic inclusion in Section C. The plan and its interpretation remained contested, and Assam ultimately did not remain in that group.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = 'c1b743e4-1ed4-4e7d-aaed-1c72b25a7128' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'gopinath-bardoloi' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-c1b743e4-1ed4-4e7d-aaed-1c72b25a7128-en-551","language":"English","title":"Kalicharan Brahma","topic_slug":"kalicharan-brahma","definition":"Biographical Origin: Born Kalicharan Mech in 1860 at Kajigaon in the Goalpara/Kokrajhar region' || char(59) || ' later adopted the title Brahma upon his religious conversion. Brahma Dharma & Societal Regeneration: Initiated into the Vedic monotheistic Brahma faith by Swami Sibanarayan Paramhansa in Calcutta in 1906. Established the Brahma Dharma movement among the Bodo community to dismantle deep-rooted social vulnerabilities. Prohibited the traditional ritual sacrifice of animals and the consumption of rice-beer (Zou), which had historically driven Bodo families into severe debt to moneylenders. Promoted the sacred Yajna (fire ritual) accompanied by the Gayatri Mantra, cultivating self-respect and cultural dignity within the community. Educational & Economic Reform: Established middle schools, carpentry training workshops, and weaving centers across lower Assam to encourage vocational self-reliance. Promoted female literacy and abolished oppressive bridal price traditions.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = 'c1b743e4-1ed4-4e7d-aaed-1c72b25a7128' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'kalicharan-brahma' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-c1b743e4-1ed4-4e7d-aaed-1c72b25a7128-en-552","language":"English","title":"Bhimbar Deori","topic_slug":"bhimbar-deori","definition":"Establishment of the Assam Tribal League (1933): Co-founded the Assam Plains Tribal League in 1933, serving as its General Secretary. Unified diverse plains tribes (Deoris, Misings, Bodos, Sonowal Kacharis, Rabhas, Tiwas) into an autonomous political collective to negotiate with colonial and provincial authorities. The Line System & Protection of Tribal Lands: Campaigned against the settlement of immigrant peasants from East Bengal on indigenous ancestral territories. Led mass resistance demanding the strict enforcement and statutory strengthening of the colonial Line System, which evolved into the post-independence framework of Tribal Belts and Blocks in Assam to legally preserve tribal lands. The Bordoloi-Deori Pact (1940): Formulated an electoral and policy alliance between the Tribal League and Gopinath Bardoloi''s Congress coalition.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = 'c1b743e4-1ed4-4e7d-aaed-1c72b25a7128' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'bhimbar-deori' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-d59e8d08-cae8-433a-a994-1ae726a95e94-en-553","language":"English","title":"Assam Association","topic_slug":"assam-association","definition":"Genesis & Organizational Structure: Formed in 1903 through the initiative of middle-class intellectuals' || char(59) || ' held its inaugural annual conference at Dibrugarh in 1905. Raja Prabhat Chandra Baruah of Gauripur served as its first President' || char(59) || ' Manik Chandra Baruah served as its first General Secretary. Aims & Political Methods: Operated as the pioneer provincial political platform representing the interests of the people of Assam before the British Raj prior to the institutional spread of the Indian National Congress. Followed constitutional and moderate methods: submitting petitions, drafting memoranda, and seeking reform through regional legislative councils. Key Interventions & Achievements: Opposed the colonial administration''s heavy taxation on peasant land. Campaigned persistently against the British government''s lucrative excise policy that promoted the open sale and spread of opium (Kani). Protested the 1905 Partition of Bengal, resisting the incorporation of Assam into the newly created province of ''Eastern Bengal and Assam''.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = 'd59e8d08-cae8-433a-a994-1ae726a95e94' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'assam-association' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-d59e8d08-cae8-433a-a994-1ae726a95e94-en-554","language":"English","title":"Asom Chatra Sanmilan","topic_slug":"asom-chatra-sanmilan","definition":"Founding Conference: Established at its first annual session held in Guwahati in December 1916. The historic inaugural session was presided over by Lakshminath Bezbaruah. Official Mouthpiece (Milan): Launched the literary journal Milan in 1923, edited by leaders like Chandranath Sarmah and Sonaram Choudhury. The magazine served as an intellectual medium for Assamese poetry, essays, historical inquiry, and political commentary. Role in Language & Literature: Mandated the systematic preservation of Assamese linguistic identity, documenting oral folk vocabulary and supporting young authors. Demanded the introduction of Assamese as the medium of instruction at secondary and university levels across the province. Evolution into Political Activism: Initially formed as a strictly non-political, socio-cultural body focused on literary awakening and moral discipline among the youth. Under the leadership of Chandranath Sarmah and Hemchandra Baruah, the student body radicalized in response to the Jallianwala Bagh massacre (1919) and the Non-Cooperation call (1920–21).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = 'd59e8d08-cae8-433a-a994-1ae726a95e94' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'asom-chatra-sanmilan' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-d59e8d08-cae8-433a-a994-1ae726a95e94-en-555","language":"English","title":"Tarun Ram Phukan","topic_slug":"tarun-ram-phukan","definition":"Title & Leadership: Popularly revered as \"Deshbhakta\" (Patriot of the Nation)' || char(59) || ' his death anniversary on July 28 is observed as Deshbhakta Divas in Assam. Renounced a lucrative legal practice as a Barrister to lead the Non-Cooperation Movement (1921) in Assam following Mahatma Gandhi''s tour of the province. Key Political Roles: Served as President of the Assam Provincial Congress Committee (APCC). 41st Pandu Congress Session (1926): As the Chairman of the Reception Committee, Phukan was instrumental in hosting the 41st session of the Indian National Congress at Pandu (Guwahati) in 1926. This successfully integrated Assam''s regional concerns into the pan-Indian national consciousness. Swarajist Politics: Sided with Motilal Nehru and Chittaranjan Das to join the Swaraj Party within the central legislative apparatus, advocating obstructionist tactics from inside the councils. Oratory & Literary Output: An orator who published literary and reflective essays, including Mor Sikhar Katha and works on hunting and wildlife preservation.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = 'd59e8d08-cae8-433a-a994-1ae726a95e94' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'tarun-ram-phukan' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
