UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-d59e8d08-cae8-433a-a994-1ae726a95e94-en-558","language":"English","title":"Bhimbar Deori","topic_slug":"bhimbar-deori","definition":"Establishment of the Assam Tribal League (1933): Co-founded the Assam Plains Tribal League in 1933, serving as its General Secretary. Unified diverse plains tribes (Deoris, Misings, Bodos, Sonowal Kacharis, Rabhas, Tiwas) into an autonomous political collective to negotiate with colonial and provincial authorities. The Line System & Protection of Tribal Lands: Campaigned against the settlement of immigrant peasants from East Bengal on indigenous ancestral territories. Led mass resistance demanding the strict enforcement and statutory strengthening of the colonial Line System, which evolved into the post-independence framework of Tribal Belts and Blocks in Assam to legally preserve tribal lands. The Bordoloi-Deori Pact (1940): Formulated an electoral and policy alliance between the Tribal League and Gopinath Bardoloi''s Congress coalition.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = 'd59e8d08-cae8-433a-a994-1ae726a95e94' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'bhimbar-deori' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-4926a92f-6567-469f-989d-035615fdc7f1-en-559","language":"English","title":"Baptist Missionaries, Girls’ Schools and Print","topic_slug":"baptist-missionaries-girls-schools-and-print","definition":"American Baptist missionaries arrived in Assam in the 1830s. Mission stations, missionary wives and local supporters helped establish early girls’ schools in places including Sibsagar, Nagaon and Guwahati. These schools introduced organized instruction and boarding arrangements at a time when girls’ access to education was very limited. The work combined educational aims with Christian missionary activity, so it should be understood in its historical context rather than as a purely secular programme. Orunodoi , first published in 1846, widened Assamese-language print culture. Its educational and social-reform writing helped make questions of literacy, schooling and women’s status part of public discussion. Missionaries also produced vernacular reading material, while schooling remained constrained by child marriage, purdah and household seclusion, fears of conversion, and a shortage of trained women teachers.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '4926a92f-6567-469f-989d-035615fdc7f1' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'baptist-missionaries-girls-schools-and-print' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-4926a92f-6567-469f-989d-035615fdc7f1-en-560","language":"English","title":"Rajabala Das and Women’s Higher Education","topic_slug":"rajabala-das-and-womens-higher-education","definition":"Rajabala Das (1895–1971) was an educator and a pioneer of women’s higher education in Assam. A 2023 Times of India account identifies her as the first woman graduate from Assam and records that she was headmistress of Panbazar Girls’ High School before helping establish Gauhati Girls’ College in 1939 on the high school premises. The college was later renamed Handique Girls’ College in honour of its benefactor, Radhakanta Handique. Her contribution was institutional: she helped turn a girls’ school setting into a college-level opportunity for women, at a time when higher education was rarely accessible to them.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '4926a92f-6567-469f-989d-035615fdc7f1' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'rajabala-das-and-womens-higher-education' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-4926a92f-6567-469f-989d-035615fdc7f1-en-561","language":"English","title":"Chandraprabha Saikiani and Women’s Political Organization","topic_slug":"chandraprabha-saikiani-and-womens-political-organization","definition":"Chandraprabha Saikiani (1901–1972) was an Assamese educator, writer and social reformer. She advocated girls’ education and women’s participation in public life, challenged caste and gender restrictions, and spoke against practices such as child marriage and the seclusion of women. Her work connected education with social equality: schooling was a way for women to gain knowledge, confidence and a public voice. Under her leadership, the Assam Pradeshik Mahila Samiti was established in 1926. The organization gave women a collective platform to discuss education, social reform and civic participation. Saikiani also took part in the freedom movement and used public meetings and writing to broaden women’s political presence.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '4926a92f-6567-469f-989d-035615fdc7f1' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'chandraprabha-saikiani-and-womens-political-organization' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-4926a92f-6567-469f-989d-035615fdc7f1-en-562","language":"English","title":"Amal Prabha Das and Gandhian Constructive Work","topic_slug":"amal-prabha-das-and-gandhian-constructive-work","definition":"Amal Prabha Das (1911–1994) was a Gandhian social worker. In 1939, she and her family began a small ashram at Sarania, Guwahati, and trained in village industries such as oil pressing, paper-making and bee-keeping. She promoted khadi, spinning and practical work that could support local self-reliance. In 1946, the Kasturba Gram Sevika Vidyalaya was inaugurated at Sarania' || char(59) || ' the institution trained village women in pre-basic and adult education, sanitation, maternity and child welfare, and village industries. Her constructive work linked education to livelihoods and community service. She supported women’s economic independence, helped care for children and widowed women after the 1950 earthquake, and accompanied Vinoba Bhave on a Bhoodan-Gramdan padyatra in 1961–62. The Jamnalal Bajaj Foundation biography documents these activities and the Sarania Ashram’s development.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '4926a92f-6567-469f-989d-035615fdc7f1' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'amal-prabha-das-and-gandhian-constructive-work' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-4926a92f-6567-469f-989d-035615fdc7f1-en-563","language":"English","title":"Sadou Asom Lekhika Samaroh Samiti","topic_slug":"sadou-asom-lekhika-samaroh-samiti","definition":"The Sadou Asom Lekhika Samaroh Samiti, an organization of women writers, was formed in 1974' || char(59) || ' Sheela Borthakur is identified as its founder and founding president. Its purpose is to unite and support women through creative work, especially literature. The Samiti provides platforms for discussion and publication and helps make women’s writing more visible in Assamese public life. Its recorded publications include Lekhikar Jibani (four volumes), Dharmeswari Devi Baruani Rachana Sambhar (1992), Mahasweta Barerohonia , Borma Tomak (an anthology of short stories), and Satabdir Sadhu . A separately verifiable publication is Lekhikar Granthapanji, Volume 1 (2000), a bibliography of women writers issued by the Samiti. The Gauhati University/INFLIBNET repository includes a history of the Samiti covering 1974–2016. Do not conflate its publications with works credited to the separate Assam Lekhika Sangha.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '4926a92f-6567-469f-989d-035615fdc7f1' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'sadou-asom-lekhika-samaroh-samiti' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-4926a92f-6567-469f-989d-035615fdc7f1-en-564","language":"English","title":"Selected sources","topic_slug":"selected-sources","definition":"Nowgong Mission School — School History — local chronology of early mission girls’ schools. - Yale Archives — Miles Bronson Family Papers — identifies Miles Bronson and his wife Ruth in the Nowgong mission context. - Times of India — “Torchbearer of women’s education” (3 Dec 2023) — Rajabala Das, Panbazar Girls’ High School and Gauhati Girls’ College. - Jamnalal Bajaj Foundation — Amalprava Das biography (1981).pdf) — Sarania Ashram, village industries, basic education and welfare work. - AssamInfo — Chandraprabha Saikiani biography — 1926 Samiti founding and social-reform overview. - Sadou Asom Lekhika Samaroh Samiti and Gauhati University/INFLIBNET research record — organization history and research coverage. - Archive.org — Lekhikar Granthapanji, Vol. 1 — catalog and publication record.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '4926a92f-6567-469f-989d-035615fdc7f1' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'selected-sources' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-8ee85d17-f2bb-4941-a741-ad9b805d97b7-en-565","language":"English","title":"Baptist Missionaries, Girls’ Schools and Print","topic_slug":"baptist-missionaries-girls-schools-and-print","definition":"American Baptist missionaries arrived in Assam in the 1830s. Mission stations, missionary wives and local supporters helped establish early girls’ schools in places including Sibsagar, Nagaon and Guwahati. These schools introduced organized instruction and boarding arrangements at a time when girls’ access to education was very limited. The work combined educational aims with Christian missionary activity, so it should be understood in its historical context rather than as a purely secular programme. Orunodoi , first published in 1846, widened Assamese-language print culture. Its educational and social-reform writing helped make questions of literacy, schooling and women’s status part of public discussion. Missionaries also produced vernacular reading material, while schooling remained constrained by child marriage, purdah and household seclusion, fears of conversion, and a shortage of trained women teachers. Source-check on the school question: the supplied question bank asks for the couple associated with the first girls’ boarding school in Nowgong.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '8ee85d17-f2bb-4941-a741-ad9b805d97b7' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'baptist-missionaries-girls-schools-and-print' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-8ee85d17-f2bb-4941-a741-ad9b805d97b7-en-566","language":"English","title":"Rajabala Das and Women’s Higher Education","topic_slug":"rajabala-das-and-womens-higher-education","definition":"Rajabala Das (1895–1971) was an educator and a pioneer of women’s higher education in Assam. A 2023 Times of India account identifies her as the first woman graduate from Assam and records that she was headmistress of Panbazar Girls’ High School before helping establish Gauhati Girls’ College in 1939 on the high school premises. The college was later renamed Handique Girls’ College in honour of its benefactor, Radhakanta Handique. Her contribution was institutional: she helped turn a girls’ school setting into a college-level opportunity for women, at a time when higher education was rarely accessible to them. Wording check: the source identifies Rajabala as headmistress of Panbazar Girls’ High School and founder of the college' || char(59) || ' it does not establish that she founded the high school. The supplied question bank’s phrasing should therefore be checked.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '8ee85d17-f2bb-4941-a741-ad9b805d97b7' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'rajabala-das-and-womens-higher-education' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-8ee85d17-f2bb-4941-a741-ad9b805d97b7-en-567","language":"English","title":"Chandraprabha Saikiani and Women’s Political Organization","topic_slug":"chandraprabha-saikiani-and-womens-political-organization","definition":"Chandraprabha Saikiani (1901–1972) was an Assamese educator, writer and social reformer. She advocated girls’ education and women’s participation in public life, challenged caste and gender restrictions, and spoke against practices such as child marriage and the seclusion of women. Her work connected education with social equality: schooling was a way for women to gain knowledge, confidence and a public voice. Under her leadership, the Assam Pradeshik Mahila Samiti was established in 1926. The organization gave women a collective platform to discuss education, social reform and civic participation. Saikiani also took part in the freedom movement and used public meetings and writing to broaden women’s political presence. The specific resolutions adopted at the Samiti’s inaugural meeting should be checked against its proceedings' || char(59) || ' summaries differ in wording.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '8ee85d17-f2bb-4941-a741-ad9b805d97b7' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'chandraprabha-saikiani-and-womens-political-organization' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-8ee85d17-f2bb-4941-a741-ad9b805d97b7-en-568","language":"English","title":"Amal Prabha Das and Gandhian Constructive Work","topic_slug":"amal-prabha-das-and-gandhian-constructive-work","definition":"Amal Prabha Das (1911–1994) was a Gandhian social worker. In 1939, she and her family began a small ashram at Sarania, Guwahati, and trained in village industries such as oil pressing, paper-making and bee-keeping. She promoted khadi, spinning and practical work that could support local self-reliance. In 1946, the Kasturba Gram Sevika Vidyalaya was inaugurated at Sarania' || char(59) || ' the institution trained village women in pre-basic and adult education, sanitation, maternity and child welfare, and village industries. Her constructive work linked education to livelihoods and community service. She supported women’s economic independence, helped care for children and widowed women after the 1950 earthquake, and accompanied Vinoba Bhave on a Bhoodan-Gramdan padyatra in 1961–62. The Jamnalal Bajaj Foundation biography documents these activities and the Sarania Ashram’s development.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '8ee85d17-f2bb-4941-a741-ad9b805d97b7' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'amal-prabha-das-and-gandhian-constructive-work' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-8ee85d17-f2bb-4941-a741-ad9b805d97b7-en-569","language":"English","title":"Sadou Asom Lekhika Samaroh Samiti","topic_slug":"sadou-asom-lekhika-samaroh-samiti","definition":"The Sadou Asom Lekhika Samaroh Samiti, an organization of women writers, was formed in 1974' || char(59) || ' Sheela Borthakur is identified as its founder and founding president. Its purpose is to unite and support women through creative work, especially literature. The Samiti provides platforms for discussion and publication and helps make women’s writing more visible in Assamese public life. Its recorded publications include Lekhikar Jibani (four volumes), Dharmeswari Devi Baruani Rachana Sambhar (1992), Mahasweta Barerohonia , Borma Tomak (an anthology of short stories), and Satabdir Sadhu . A separately verifiable publication is Lekhikar Granthapanji, Volume 1 (2000), a bibliography of women writers issued by the Samiti. The Gauhati University/INFLIBNET repository includes a history of the Samiti covering 1974–2016. Do not conflate its publications with works credited to the separate Assam Lekhika Sangha.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '8ee85d17-f2bb-4941-a741-ad9b805d97b7' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'sadou-asom-lekhika-samaroh-samiti' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-8ee85d17-f2bb-4941-a741-ad9b805d97b7-en-570","language":"English","title":"Selected sources","topic_slug":"selected-sources","definition":"Nowgong Mission School — School History — local chronology of early mission girls’ schools. - Yale Archives — Miles Bronson Family Papers — identifies Miles Bronson and his wife Ruth in the Nowgong mission context. - Times of India — “Torchbearer of women’s education” (3 Dec 2023) — Rajabala Das, Panbazar Girls’ High School and Gauhati Girls’ College. - Jamnalal Bajaj Foundation — Amalprava Das biography (1981).pdf) — Sarania Ashram, village industries, basic education and welfare work. - AssamInfo — Chandraprabha Saikiani biography — 1926 Samiti founding and social-reform overview. - Sadou Asom Lekhika Samaroh Samiti and Gauhati University/INFLIBNET research record — organization history and research coverage. - Archive.org — Lekhikar Granthapanji, Vol. 1 — catalog and publication record.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '8ee85d17-f2bb-4941-a741-ad9b805d97b7' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'selected-sources' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-2c992f2f-091d-42f9-a730-3f0b60740b12-en-571","language":"English","title":"Baptist Missionaries, Girls’ Schools and Print","topic_slug":"baptist-missionaries-girls-schools-and-print","definition":"American Baptist missionaries arrived in Assam in the 1830s. Mission stations, missionary wives and local supporters helped establish early girls’ schools in places including Sibsagar, Nagaon and Guwahati. These schools introduced organized instruction and boarding arrangements at a time when girls’ access to education was very limited. The work combined educational aims with Christian missionary activity, so it should be understood in its historical context rather than as a purely secular programme. Orunodoi , first published in 1846, widened Assamese-language print culture. Its educational and social-reform writing helped make questions of literacy, schooling and women’s status part of public discussion. Missionaries also produced vernacular reading material, while schooling remained constrained by child marriage, purdah and household seclusion, fears of conversion, and a shortage of trained women teachers. Source-check on the school question: the supplied question bank asks for the couple associated with the first girls’ boarding school in Nowgong.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '2c992f2f-091d-42f9-a730-3f0b60740b12' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'baptist-missionaries-girls-schools-and-print' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
