UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-2c992f2f-091d-42f9-a730-3f0b60740b12-en-576","language":"English","title":"Selected sources","topic_slug":"selected-sources","definition":"Nowgong Mission School — School History — local chronology of early mission girls’ schools. - Yale Archives — Miles Bronson Family Papers — identifies Miles Bronson and his wife Ruth in the Nowgong mission context. - Times of India — “Torchbearer of women’s education” (3 Dec 2023) — Rajabala Das, Panbazar Girls’ High School and Gauhati Girls’ College. - Jamnalal Bajaj Foundation — Amalprava Das biography (1981).pdf) — Sarania Ashram, village industries, basic education and welfare work. - AssamInfo — Chandraprabha Saikiani biography — 1926 Samiti founding and social-reform overview. - Sadou Asom Lekhika Samaroh Samiti and Gauhati University/INFLIBNET research record — organization history and research coverage. - Archive.org — Lekhikar Granthapanji, Vol. 1 — catalog and publication record.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '2c992f2f-091d-42f9-a730-3f0b60740b12' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'selected-sources' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35f-en-577","language":"English","title":"The process and types of Communication: verbal-non-verbal","topic_slug":"the-process-and-types-of-communication-verbal-non-verbal","definition":"Verbal and non-verbal communication are two primary types of communication that differ in the use of language. Verbal communication involves the use of spoken or written words, while non-verbal communication conveys messages without words through body language, facial expressions, gestures, and tone of voice. The communication process consists of key elements: sender, message, channel, receiver, feedback, and context. In verbal communication, words are the main tools, and clarity of speech or writing is essential. It is commonly used in conversations, speeches, and written documents. Non-verbal communication often complements verbal messages—for example, a smile can reinforce a friendly tone. It can also contradict verbal messages, such as saying “I’m fine” while frowning. Non-verbal cues are especially important in cross-cultural interactions where language barriers exist. Both types are interdependent and contribute significantly to the overall effectiveness of communication.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-process-and-types-of-communication-verbal-non-verbal' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35f-en-578","language":"English","title":"oral-written-written communication","topic_slug":"oral-written-written-communication","definition":"Oral and written communication are two forms of verbal communication distinguished by the medium used to deliver the message. Oral communication involves spoken words, while written communication uses written or printed words to convey information. Oral communication is immediate and interactive, making it ideal for discussions, interviews, meetings, and presentations. It allows for instant feedback and clarification but may lack permanence and precision. Examples include face-to-face conversations, phone calls, and public speaking. Written communication, on the other hand, is more structured and permanent, suitable for formal records, instructions, reports, and emails. It allows time for planning and editing but lacks immediate feedback. Both forms require clarity, coherence, and audience awareness. In academic settings, students use written communication for assignments and exams, while oral skills are essential for seminars and group discussions.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'oral-written-written-communication' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35f-en-579","language":"English","title":"formal–informal communicationmodern forms of communication","topic_slug":"formalinformal-communicationmodern-forms-of-communication","definition":"Formal and informal communication refer to the style, structure, and context in which messages are exchanged in organizations and social settings. Formal communication follows official channels and protocols, while informal communication occurs spontaneously through personal interactions. Modern forms of communication include digital tools like email, social media, video conferencing, and instant messaging. Formal communication is typically found in workplaces, academic institutions, and official correspondence. It follows a hierarchical structure, uses standard language, and maintains records—for example, official memos, reports, or academic emails. Informal communication, often called the \"grapevine,\" is casual, faster, and more personal, such as conversations during breaks or text messages among friends. While informal communication builds relationships, it may spread rumors or misinformation. Modern forms of communication have transformed how people connect, enabling instant global interaction through platforms like WhatsApp, Zoom, and LinkedIn.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'formalinformal-communicationmodern-forms-of-communication' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35f-en-580","language":"English","title":"Qualities of effective communication","topic_slug":"qualities-of-effective-communication","definition":"Effective communication is the successful exchange of information in a way that is clearly understood, respected, and acted upon by the receiver. It involves not only transmitting a message but ensuring it is received and interpreted as intended. Effective communication is essential in all areas of life, including education, work, and personal relationships. It requires a combination of skills such as clarity, active listening, empathy, and cultural awareness. A communicator must be able to express ideas logically and concisely while also being receptive to feedback. It minimizes misunderstandings and builds trust between individuals. Good communication also involves adapting the message to the audience’s level of understanding and choosing the right medium. It is not just about speaking or writing well but also about creating an environment where open and honest dialogue can occur. These qualities collectively enhance the accuracy and impact of the message.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'qualities-of-effective-communication' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35f-en-581","language":"English","title":"reading-listening intelligently-thinking","topic_slug":"reading-listening-intelligently-thinking","definition":"Reading and listening intelligently, along with critical thinking , are essential components of effective communication that enable individuals to understand, analyze, and respond appropriately to messages. Intelligent reading and listening go beyond passive reception to active engagement with content. Intelligent reading involves focusing on purpose, identifying main ideas, understanding context, and evaluating arguments. It requires concentration, vocabulary knowledge, and the ability to infer meaning. Similarly, intelligent listening—also known as active listening —means paying full attention, avoiding interruptions, and providing feedback to confirm understanding. Both skills help students absorb information from lectures, textbooks, and discussions. Thinking critically allows individuals to assess the validity, relevance, and logic of communicated messages. It involves questioning assumptions, recognizing biases, and forming reasoned judgments. Together, these skills empower learners to participate meaningfully in academic and professional discourse.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'reading-listening-intelligently-thinking' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35f-en-582","language":"English","title":"and planning-using appropriate language-using","topic_slug":"and-planning-using-appropriate-language-using","definition":"Planning and using appropriate language are crucial steps in crafting effective messages that suit the audience, purpose, and context of communication. Planning involves organizing thoughts and selecting content, while appropriate language ensures clarity, respect, and relevance. Before communicating, individuals should define the purpose, identify the audience, and outline key points to include. Planning helps structure the message logically, whether in speech or writing, and reduces the chance of errors or omissions. Using appropriate language means choosing words that are clear, accurate, and suitable for the listener or reader’s background, education level, and cultural context. It includes avoiding jargon in general communication and using respectful, inclusive terms. For example, formal language is expected in academic essays, while simpler terms may be better for public announcements. Appropriate language also considers tone—whether persuasive, informative, or empathetic—based on the situation.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'and-planning-using-appropriate-language-using' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35f-en-583","language":"English","title":"appropriate channel-cultural sensitivity-showing empathy-not prejudging-clarity-avoiding distractions-showing respect","topic_slug":"appropriate-channel-cultural-sensitivity-showing-empathy-not-prejudging-clarity-avoiding-distractions-showing-respect","definition":"Choosing the appropriate channel, practicing cultural sensitivity, showing empathy, avoiding prejudgment, ensuring clarity, minimizing distractions, and showing respect are interrelated qualities that enhance communication effectiveness across diverse contexts. The appropriate channel refers to selecting the best medium—such as face-to-face, phone, email, or video call—based on the message’s urgency, complexity, and audience. Cultural sensitivity involves recognizing and respecting differences in language, values, and communication styles among people from various backgrounds. Empathy means understanding others’ feelings and perspectives, which builds trust and rapport. Not prejudging requires suspending assumptions or stereotypes about others before listening fully. Clarity ensures the message is straightforward and free of confusion. Avoiding distractions —like noise, multitasking, or emotional interference—helps maintain focus. Showing respect includes listening without interruption, using polite language, and acknowledging others’ viewpoints, fostering a positive communication environment.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'appropriate-channel-cultural-sensitivity-showing-empathy-not-prejudging-clarity-avoiding-distractions-showing-respect' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35f-en-584","language":"English","title":"barriers to effective communication","topic_slug":"barriers-to-effective-communication","definition":"Barriers to effective communication are obstacles that distort or disrupt the transmission and understanding of messages between individuals or groups. These barriers can be linguistic, psychological, physical, or cultural in nature. Linguistic barriers arise from differences in language, vocabulary, or accent, making it difficult for the receiver to understand the message. Psychological barriers include emotions like anger, stress, or prejudice, which affect how messages are sent or received. Physical barriers involve noise, poor lighting, or faulty technology that interfere with the communication process. Cultural barriers occur when differing values, beliefs, or customs lead to misunderstandings. Organizational barriers, such as hierarchical structures, can delay or filter information. Semantic barriers happen when words are interpreted differently—for example, technical terms misunderstood by non-experts. Recognizing and addressing these barriers is essential for improving communication accuracy and effectiveness.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'barriers-to-effective-communication' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-585","language":"English","title":"In this unit","topic_slug":"in-this-unit","definition":"This unit is designed to develop students'' listening and speaking skills in both formal and informal contexts, with a focus on enhancing effective communication through structured practice. The unit introduces learners to core communication competencies such as active listening, clear verbal expression, and appropriate non-verbal behavior. It emphasizes real-life applications including group discussions, interviews, oral presentations, and public speaking. Students will engage in interactive classroom activities that simulate authentic communicative situations. The goal is to build confidence and fluency while fostering empathy and interpersonal sensitivity. Through guided exercises, students learn to interpret spoken messages accurately and respond appropriately across diverse settings. This foundation supports academic success and prepares students for professional communication environments.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'in-this-unit' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-586","language":"English","title":"students will be acquainted with the attributes of effective speech like confidence","topic_slug":"students-will-be-acquainted-with-the-attributes-of-effective-speech-like-confidence","definition":"Effective speech refers to verbal communication that is clear, impactful, and well-received by the audience, largely due to the speaker''s personal and expressive qualities. Among the key attributes of effective speech, confidence plays a foundational role. A confident speaker appears self-assured, maintains eye contact, and uses a steady voice, which enhances credibility and audience engagement. Confidence reduces hesitation and filler words, allowing for smoother delivery. It also helps the speaker manage nervousness and respond effectively to questions or interruptions. While confidence can be developed through practice, it begins with thorough preparation and positive self-perception. In academic and professional settings, confident speakers are more likely to influence others and convey ideas persuasively.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'students-will-be-acquainted-with-the-attributes-of-effective-speech-like-confidence' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-587","language":"English","title":"clarity","topic_slug":"clarity","definition":"Clarity in speech refers to the quality of being easily understood, where the speaker’s message is conveyed precisely and without confusion. A clear speaker uses simple and accurate language, organizes thoughts logically, and avoids ambiguity or complex jargon unless necessary. Clarity ensures that listeners grasp the intended meaning quickly and correctly. It involves proper articulation, well-structured sentences, and appropriate pacing. In both formal and informal communication, clarity prevents misunderstandings and enhances information retention. Teachers, professionals, and public speakers must prioritize clarity to ensure effective transmission of ideas. Even with strong content, poor clarity can undermine the entire communication process.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'clarity' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-588","language":"English","title":"audibility","topic_slug":"audibility","definition":"Audibility refers to the ability of a speaker’s voice to be heard clearly by the intended audience in a given environment. An audible speaker projects their voice sufficiently so that all listeners, even those at a distance, can hear without strain. This requires proper breath control, vocal strength, and awareness of the acoustic setting. Factors such as background noise, room size, and use of microphones influence audibility. In classrooms or public gatherings, poor audibility leads to disengagement and miscommunication. Students must learn to modulate volume according to the setting—louder in large halls, softer in small groups—while maintaining natural tone. Audibility is not about shouting but about controlled vocal projection.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'audibility' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-589","language":"English","title":"appropriate body language","topic_slug":"appropriate-body-language","definition":"Appropriate body language refers to non-verbal cues—such as facial expressions, gestures, posture, and eye contact—that support and enhance spoken communication. Effective body language aligns with the speaker’s message, reinforcing sincerity and engagement. For instance, standing upright conveys confidence, while nodding shows attentiveness. Gestures should be natural and purposeful, emphasizing key points without distraction. Eye contact builds trust and connection with the audience, especially in formal settings like interviews or presentations. Inappropriate body language—such as fidgeting, slouching, or avoiding gaze—can undermine credibility. Since non-verbal signals are often interpreted subconsciously, mastering them is crucial for holistic communication.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'appropriate-body-language' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-590","language":"English","title":"intonation etc","topic_slug":"intonation-etc","definition":"Intonation refers to the variation in pitch and tone of voice during speech, which helps convey meaning, emotion, and emphasis. It plays a critical role in distinguishing statements from questions, expressing surprise or sarcasm, and highlighting important information. For example, rising intonation typically signals a question, while falling intonation indicates a statement. Proper intonation prevents monotony and keeps the listener engaged. In English, incorrect intonation can lead to misunderstandings, even if grammar and vocabulary are correct. Along with stress and rhythm, intonation forms part of prosody—the musical quality of speech. Mastery of intonation enhances both clarity and expressiveness in spoken communication.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'intonation-etc' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-591","language":"English","title":"Listening enhances our understanding and enables us to process ideas and arguments better.","topic_slug":"listening-enhances-our-understanding-and-enables-us-to-process-ideas-and-arguments-better","definition":"Listening is an active cognitive process that involves receiving, interpreting, and responding to spoken messages, which significantly improves comprehension and critical thinking. Effective listening allows individuals to grasp complex ideas, follow logical arguments, and identify key points in discussions or lectures. It goes beyond hearing by requiring attention, memory, and analysis. In academic contexts, strong listening skills help students absorb information, take accurate notes, and participate meaningfully. In professional environments, listening supports decision-making and problem-solving. By focusing on content and context, listeners can evaluate the strength of arguments and detect underlying assumptions. Thus, listening is not passive but a dynamic skill central to learning and reasoning.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'listening-enhances-our-understanding-and-enables-us-to-process-ideas-and-arguments-better' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-592","language":"English","title":"Students will be trained to acquire the following skills","topic_slug":"students-will-be-trained-to-acquire-the-following-skills","definition":"Communication skills training involves systematic instruction and practice in listening and speaking abilities necessary for academic, professional, and social success. This unit provides structured learning experiences to develop a range of oral communication competencies. Students engage in exercises that build both receptive (listening) and productive (speaking) skills. The training is outcome-oriented, focusing on real-world applications such as interviews, group discussions, and presentations. Activities are designed to be interactive, allowing for immediate feedback and improvement. Through repetition and guided practice, students internalize effective communication strategies. The ultimate aim is to produce confident, articulate, and empathetic communicators.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'students-will-be-trained-to-acquire-the-following-skills' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-593","language":"English","title":"Listening for detailed and specific information","topic_slug":"listening-for-detailed-and-specific-information","definition":"Listening for detailed and specific information involves focusing on precise facts, figures, names, dates, or instructions within a spoken message. This skill is essential in academic lectures, workplace briefings, and daily conversations where accuracy matters. The listener must concentrate on key details while filtering out less relevant content. Techniques include anticipating information types, noting keywords, and using context clues. For example, in a weather forecast, one listens for temperature, time, and location. In exams, this skill helps answer comprehension questions correctly. It requires sustained attention and often note-taking to retain specifics accurately.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'listening-for-detailed-and-specific-information' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-594","language":"English","title":"Understanding the speaker’s intent and attitude - Introducing- and others - Asking for clarification","topic_slug":"understanding-the-speakers-intent-and-attitude-introducing-and-others-asking-for-clarification","definition":"Understanding the speaker’s intent and attitude means identifying not just what is said, but why it is said and the emotion or stance behind it. Intent refers to the speaker’s purpose—whether to inform, persuade, complain, or apologize—while attitude reflects their feelings, such as enthusiasm, sarcasm, or frustration. This requires attention to tone, intonation, word choice, and body language. For instance, a flat tone may indicate disinterest, while fast speech may suggest urgency. In introductions, speakers must clearly state names, roles, and context to establish rapport. Asking for clarification involves politely requesting repetition or explanation using phrases like “Could you please rephrase that?” or “What do you mean by…?” These skills ensure accurate interpretation and smooth interaction.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'understanding-the-speakers-intent-and-attitude-introducing-and-others-asking-for-clarification' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-595","language":"English","title":"giving directions/instructions - Expressing gratitude","topic_slug":"giving-directions-instructions-expressing-gratitude","definition":"Giving directions/instructions involves clearly guiding someone on how to perform a task or reach a location, while expressing gratitude means verbally acknowledging appreciation for help or kindness. Effective directions are sequential, specific, and use simple language. For example, “Turn left at the post office, then walk 100 meters straight” is clearer than “Go that way.” Landmarks, distances, and action verbs improve clarity. Instructions in workplaces or classrooms must be unambiguous to prevent errors. Expressing gratitude strengthens relationships and shows politeness. Phrases like “Thank you,” “I really appreciate it,” or “That was very kind of you” are common. The tone should match the situation—formal in professional settings, warm in personal ones.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'giving-directions-instructions-expressing-gratitude' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-596","language":"English","title":"making requests","topic_slug":"making-requests","definition":"Making requests refers to politely asking someone to do something, requiring appropriate language and tone to ensure cooperation. Effective requests consider the listener’s willingness and status, using modal verbs like “could,” “would,” or “may” to soften the demand. For example, “Could you please pass the notebook?” is more polite than “Give me the notebook.” Indirect forms such as “Would it be possible to…?” are often used in formal contexts. The speaker should maintain eye contact and a respectful tone. In academic or workplace settings, poorly phrased requests may be ignored or misinterpreted. Therefore, mastering request strategies enhances interpersonal effectiveness.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'making-requests' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-597","language":"English","title":"congratulating","topic_slug":"congratulating","definition":"Congratulating is the act of expressing praise and joy for someone’s achievement or special occasion. It strengthens social bonds and acknowledges effort or success, whether in academics, sports, or personal life. Effective congratulations are timely, sincere, and specific. For example, “Congratulations on winning the debate competition—you spoke so confidently!” is better than a generic “Good job.” In formal settings, written notes or public announcements may be used' || char(59) || ' in informal ones, verbal praise suffices. Tone should be warm and enthusiastic. Avoiding jealousy or downplaying the achievement is essential to maintain positive relationships.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'congratulating' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-598","language":"English","title":"apologizing etc. - Agreeing/disagreeing","topic_slug":"apologizing-etc-agreeing-disagreeing","definition":"Apologizing is expressing regret for a mistake or offense, while agreeing/disagreeing involves showing alignment or divergence with someone’s opinion in a respectful manner. An effective apology includes acknowledgment of the error, expression of regret, and, when possible, a commitment to change—e.g., “I’m sorry I was late' || char(59) || ' I’ll manage my time better.” It restores trust and shows accountability. In discussions, agreeing can be expressed with phrases like “I agree,” “That’s true,” or “Exactly.” Disagreeing politely requires tact: “I see your point, but I think…” or “I respect that, however…” helps maintain harmony. Both skills are vital for conflict resolution and constructive dialogue.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'apologizing-etc-agreeing-disagreeing' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-599","language":"English","title":"scenario","topic_slug":"scenario","definition":"A scenario is a description of a possible situation or sequence of events, often used in communication exercises to simulate real-life interactions. In language learning, scenarios provide context for practicing listening and speaking skills in authentic settings—such as ordering food, handling complaints, or attending meetings. Students role-play within the scenario to apply vocabulary, tone, and politeness strategies. Scenarios can be formal (job interview) or informal (meeting a friend). They help learners anticipate language needs and develop situational awareness. Teachers design scenarios to target specific communication goals, making them a vital tool in skill-based instruction.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'scenario' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-600","language":"English","title":"picture","topic_slug":"picture","definition":"Picture description is a speaking activity where students observe an image and verbally explain its content, context, and implied meaning. This skill helps develop observational ability, vocabulary, and narrative structure. Students learn to describe people, objects, actions, settings, and emotions shown in the picture. They organize their description logically—often moving from foreground to background or left to right. In exams and assessments, picture descriptions test fluency and coherence. They are also used in interviews and presentations. Using present tense and descriptive adjectives enhances vividness and clarity.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'picture' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-601","language":"English","title":"telephonic or the visual mode.","topic_slug":"telephonic-or-the-visual-mode","definition":"Telephonic and visual mode interviews refer to job or academic interviews conducted over phone or video platforms like Zoom, Skype, or Google Meet. In telephonic interviews , candidates cannot rely on body language, so clarity of speech, tone, and active listening become crucial. Background noise and connection issues must be managed. In visual (video) interviews , participants must also attend to camera presence, lighting, framing, and virtual etiquette—such as looking at the camera and minimizing distractions. Both formats require preparation, professionalism, and technical readiness. These modes are increasingly common in remote hiring and admissions processes.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'telephonic-or-the-visual-mode' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-602","language":"English","title":"body language etc.","topic_slug":"body-language-etc","definition":"Body language in public speaking includes non-verbal behaviors such as gestures, facial expressions, posture, and eye contact that support and reinforce verbal communication. Effective body language enhances message delivery by conveying confidence, enthusiasm, and sincerity. Purposeful gestures emphasize key points, while facial expressions reflect the emotional tone of the speech. Standing straight with open posture signals readiness and authority. Eye contact creates connection with the audience and maintains engagement. Inconsistent or distracting body language—like pacing or hand-fidgeting—can reduce credibility. Mastery of non-verbal cues is essential for impactful public speaking.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'body-language-etc' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-603","language":"English","title":"Interpersonal skills in speaking","topic_slug":"interpersonal-skills-in-speaking","definition":"Interpersonal speaking skills involve using verbal and non-verbal communication to build and maintain healthy, respectful relationships in one-on-one or small group interactions. These skills include active listening, expressing empathy, managing tone, and using appropriate language for the context. They enable individuals to share feelings, resolve conflicts, and collaborate effectively. In daily life, interpersonal communication occurs in friendships, family, and academic collaborations. Success depends on clarity, politeness, and emotional intelligence. Students learn to adapt their style based on the listener and situation, ensuring mutual understanding and respect.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'interpersonal-skills-in-speaking' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-604","language":"English","title":"Besides the above","topic_slug":"besides-the-above","definition":"Beyond the core skills , additional communication practices are integrated to ensure holistic development of speaking and listening abilities. These include handling unexpected questions, adapting to diverse audiences, and managing communication breakdowns. Students also learn cultural sensitivity in language use and awareness of regional accents. Activities may involve storytelling, debates, or impromptu speaking to build spontaneity. The aim is to create versatile communicators capable of navigating various real-world situations with confidence and clarity.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'besides-the-above' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-605","language":"English","title":"various other contexts of interpersonal communication","topic_slug":"various-other-contexts-of-interpersonal-communication","definition":"Various contexts of interpersonal communication include everyday situations such as peer discussions, teacher-student interactions, family conversations, and team collaborations. Each context has unique expectations regarding formality, tone, and language use. For example, speaking to a professor requires more formality than chatting with a roommate. Students learn to identify these differences and adjust their communication style accordingly. Role-plays simulate scenarios like resolving conflicts, giving feedback, or seeking advice. Mastery of context-aware communication fosters respect, clarity, and relationship-building.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'various-other-contexts-of-interpersonal-communication' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-606","language":"English","title":"situations requiring expression of opinions","topic_slug":"situations-requiring-expression-of-opinions","definition":"Expression of opinions involves articulating personal beliefs, judgments, or perspectives on social, academic, or personal issues in a clear and respectful manner. Students learn to state opinions using phrases like “I think,” “In my opinion,” or “I believe,” followed by supporting reasons. They are taught to distinguish opinion from fact and to respect differing viewpoints. In classroom debates or discussions, expressing opinions fosters critical thinking and confidence. The tone should remain polite, especially in group settings, to encourage open dialogue without confrontation.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'situations-requiring-expression-of-opinions' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-607","language":"English","title":"feelings","topic_slug":"feelings","definition":"Expression of feelings refers to verbally communicating one’s emotions—such as happiness, sadness, anger, or anxiety—in an appropriate and socially acceptable way. It is a key aspect of emotional intelligence and healthy relationships. Students learn to use “I” statements (e.g., “I feel upset when…”) to express emotions without blaming others. This reduces conflict and promotes understanding. In interpersonal communication, suppressing feelings can lead to misunderstandings, while excessive expression may overwhelm listeners. Therefore, balance and context are crucial. Teachers guide students to identify emotions and choose suitable words and tone.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'feelings' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-608","language":"English","title":"politeness","topic_slug":"politeness","definition":"Politeness in speaking refers to using language and behavior that shows respect, consideration, and courtesy toward others in communication. It includes using honorifics (e.g., “Sir,” “Ma’am”), please and thank you, and indirect or softened expressions in requests and disagreements. Politeness varies across cultures and contexts—what is polite in one setting may seem distant or overly formal in another. In academic and professional environments, polite speech fosters cooperation and positive relationships. Students learn to balance honesty with tact, ensuring clarity without rudeness.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'politeness' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37a-en-609","language":"English","title":"gestures and postures.","topic_slug":"gestures-and-postures","definition":"Gestures and postures are non-verbal communication elements involving hand movements and body positioning that convey meaning and attitude during speaking. Gestures —such as pointing, waving, or using hands to illustrate size or shape—can emphasize or clarify spoken words. Postures like standing straight, leaning forward, or crossing arms send signals about attention, confidence, or openness. Positive gestures enhance engagement, while negative ones (e.g., finger-pointing, slouching) may offend or distract. Students are trained to use natural, purposeful movements that support their message and reflect confidence and respect.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'gestures-and-postures' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de384-en-610","language":"English","title":"Right to Equality","topic_slug":"right-to-equality","definition":"Article 14 guarantees equality before law and equal protection of laws , ensuring no person is above the law. Article 15 prohibits discrimination on grounds of religion, race, caste, sex, or place of birth, and allows the state to make special provisions for women and children. Article 16 ensures equality in public employment, prohibiting discrimination, though it permits reservations for backward classes. Article 17 abolishes untouchability and makes its practice a punishable offense under the Protection of Civil Rights Act, 1955 . Article 18 abolishes hereditary titles (except military and academic), preventing the creation of an aristocratic class.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de384' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'right-to-equality' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de384-en-611","language":"English","title":"Right to Freedom","topic_slug":"right-to-freedom","definition":"Article 19 grants six freedoms: speech and expression, assembly, association, movement, residence, and profession. These are subject to reasonable restrictions for public order, morality, and national security. Article 20 protects against ex-post facto laws , double jeopardy, and self-incrimination. Article 21 safeguards life and personal liberty, later expanded by judicial interpretation. Article 22 provides safeguards against arbitrary arrest and detention, including the right to be informed of charges and to consult a lawyer.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de384' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'right-to-freedom' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de384-en-612","language":"English","title":"Right to Freedom of Religion","topic_slug":"right-to-freedom-of-religion","definition":"Article 25 grants freedom of conscience and the right to practice, propagate, and manage religious affairs, subject to public order and morality. Article 26 allows religious denominations to manage their own affairs. Article 27 prohibits compulsory taxation for religious purposes, and Article 28 restricts religious instruction in state-funded educational institutions.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de384' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'right-to-freedom-of-religion' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de384-en-613","language":"English","title":"Cultural and Educational Rights","topic_slug":"cultural-and-educational-rights","definition":"Article 29 protects the interests of linguistic and religious minorities , allowing them to conserve their language and culture. Article 30 grants minorities the right to establish and administer educational institutions of their choice, with protection from discriminatory state action.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de384' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'cultural-and-educational-rights' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de361-en-614","language":"English","title":"Financial System: meaning","topic_slug":"financial-system-meaning","definition":"Financial System refers to a network of institutions, markets, mechanisms, and instruments that facilitate the flow of funds among lenders, investors, and borrowers in an economy. It acts as a bridge between surplus units (those with excess funds) and deficit units (those in need of funds). The financial system ensures efficient allocation of resources by mobilizing savings and channeling them into productive investments. It provides a mechanism for payment, enables risk sharing, and supports liquidity in the economy. A well-functioning financial system enhances economic efficiency by reducing transaction costs and information asymmetry. It plays a crucial role in maintaining macroeconomic stability and fostering long-term growth. The system operates through formal structures like banks and stock exchanges, as well as informal channels in developing economies like India.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de361' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'financial-system-meaning' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de361-en-615","language":"English","title":"components","topic_slug":"components","definition":"Components of the financial system refer to the core structural elements that collectively enable the functioning of the financial framework in an economy. These include financial institutions, financial markets, financial instruments, and financial services. The financial system operates through four interlinked components. Financial institutions such as banks, insurance companies, and mutual funds act as intermediaries between savers and borrowers. Financial markets like money markets, capital markets, and foreign exchange markets provide platforms for buying and selling financial assets. Financial instruments such as shares, debentures, bonds, and bills of exchange represent claims on future income or assets. Financial services include banking, investment, insurance, and advisory services that support financial transactions. Together, these components ensure liquidity, risk diversification, and efficient capital allocation across the economy.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de361' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'components' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de361-en-616","language":"English","title":"functions •","topic_slug":"functions","definition":"Functions of the financial system refer to the essential roles it performs in an economy to ensure smooth financial operations and economic growth. These functions are critical for transforming savings into investments and maintaining economic stability. The primary function is mobilization of savings , where the system collects idle funds from households and institutions. It performs financial intermediation by channeling these savings to productive users such as businesses and governments. The system facilitates investment by providing various financial assets that match risk and return preferences. It ensures liquidity by allowing quick conversion of financial assets into cash through markets. It also enables risk sharing through diversification and insurance mechanisms. Additionally, it supports price discovery in markets and provides payment services for smooth transactions. These functions collectively enhance economic efficiency and promote confidence in the financial framework.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de361' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'functions' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de361-en-617","language":"English","title":"Financial System and Economic Development •","topic_slug":"financial-system-and-economic-development","definition":"Financial System and Economic Development refers to the relationship between a well-organized financial framework and the pace and quality of economic growth in a country. A robust financial system accelerates development by efficiently allocating resources. A developed financial system encourages higher savings and investment rates by offering safe and profitable avenues. It supports entrepreneurship and industrial expansion by providing credit to businesses, especially MSMEs. By enabling access to capital, it promotes innovation, job creation, and technological advancement. Financial inclusion ensures that even rural and low-income groups participate in economic activities. Historical evidence shows that countries with advanced financial systems, such as India post-1991 reforms, experience faster GDP growth. Moreover, financial stability contributes to macroeconomic balance, reducing vulnerabilities to crises. Thus, the financial system acts as a catalyst for equitable and sustainable development.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de361' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'financial-system-and-economic-development' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de361-en-618","language":"English","title":"Overview of the Indian Financial System","topic_slug":"overview-of-the-indian-financial-system","definition":"Overview of the Indian Financial System refers to the structure, evolution, and current state of financial institutions, markets, and regulations in India. It is a mixed system comprising formal and informal sectors, with strong regulatory oversight. The Indian financial system has evolved through three phases: pre-independence (dominated by indigenous bankers), post-independence (nationalization and regulation), and post-1991 (liberalization and modernization). It includes a wide range of institutions such as commercial banks, cooperative banks, development financial institutions (e.g., NABARD), and non-banking financial companies (NBFCs). Financial markets are segmented into money market , capital market , foreign exchange market , and derivatives market . Regulatory bodies include RBI (monetary authority), SEBI (capital markets), IRDAI (insurance), and PFRDA (pension). The system has seen rapid digitization with tools like UPI, Aadhaar, and online trading platforms. Despite progress, challenges remain in financial inclusion, credit access in rural areas, and regulatory coordination.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de361' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'overview-of-the-indian-financial-system' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37f-en-619","language":"English","title":"Financial Markets: meaning","topic_slug":"financial-markets-meaning","definition":"Financial Markets refer to institutional arrangements or platforms where financial assets such as shares, bonds, debentures, and treasury bills are created and exchanged between buyers and sellers. These markets facilitate the flow of funds from savers to borrowers, especially businesses and governments, enabling efficient allocation of capital in the economy. Financial markets are essential for economic growth as they link surplus units with deficit units. They provide liquidity, price discovery, and reduce transaction costs. These markets operate both formally (regulated exchanges) and informally (over-the-counter). They support investment, savings, and risk management by offering a variety of financial instruments. The smooth functioning of financial markets ensures that funds are directed toward productive uses, promoting industrial development and employment generation. Regulatory bodies like SEBI and RBI oversee these markets to maintain transparency and protect investor interests.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'financial-markets-meaning' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37f-en-620","language":"English","title":"classifications •","topic_slug":"classifications","definition":"Classification of Financial Markets refers to the categorization of financial markets based on maturity of instruments, nature of claims, timing of delivery, and organizational structure. This helps in understanding the structure and functioning of the financial system. Financial markets are primarily classified into money market and capital market based on the maturity period of securities. The money market deals with short-term instruments (up to one year), while the capital market handles long-term securities. Based on the nature of claims, markets are divided into debt markets (fixed returns) and equity markets (variable returns). Another classification is between primary market (new issues) and secondary market (resale of existing securities). Markets can also be categorized as spot markets (immediate delivery) and futures markets (future delivery). Organized exchanges (like NSE) and over-the-counter (OTC) markets represent structural classifications.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'classifications' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37f-en-621","language":"English","title":"Money Market: constituents","topic_slug":"money-market-constituents","definition":"Money Market is a segment of the financial market where short-term debt instruments with maturity up to one year are traded. It involves high liquidity and low risk, serving the needs of borrowers and lenders of short-term funds. The money market comprises various instruments and participants that ensure smooth short-term funding. Key constituents include Treasury Bills (T-Bills) issued by the government, Commercial Papers (CPs) issued by corporations, Certificates of Deposit (CDs) issued by banks, Call Money for overnight borrowing, and Repurchase Agreements (Repos) . Participants include commercial banks, mutual funds, insurance companies, non-banking financial companies (NBFCs), and the Reserve Bank of India. These instruments are typically traded at a discount to face value and are highly liquid. The RBI plays a central role in regulating and monitoring the money market to maintain monetary stability.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'money-market-constituents' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37f-en-622","language":"English","title":"functions","topic_slug":"functions","definition":"Functions of the Money Market refer to the roles it performs in the financial system, particularly in maintaining liquidity and supporting monetary policy. It acts as a crucial link between lenders with surplus funds and borrowers needing short-term capital. The money market enables institutions to manage their short-term liquidity requirements efficiently. It provides a platform for safe and liquid investment of temporary surplus funds. One of its key roles is assisting the central bank (RBI) in implementing monetary policy through instruments like repo and reverse repo rates. It supports the government’s borrowing program via Treasury Bills. The market also helps commercial banks meet statutory reserve requirements (CRR and SLR). By offering low-risk instruments, it ensures stability in the financial system. Additionally, it promotes the development of other financial markets by providing benchmark interest rates.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'functions' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37f-en-623","language":"English","title":"significance • Capital Market: primary & secondary markets","topic_slug":"significance-capital-market-primary-secondary-markets","definition":"Significance of the Money Market lies in its role in maintaining financial stability, supporting economic growth, and enabling effective monetary policy implementation. It serves as a critical component of the overall financial system. The money market provides a safe and liquid avenue for institutions to park surplus funds for short durations. It enables banks to meet their reserve requirements (CRR/SLR) through instruments like T-Bills and call money. For corporations, Commercial Papers offer a cost-effective way to raise short-term capital without bank loans. The market supports government fiscal operations by absorbing excess liquidity and funding budget deficits. It also acts as a barometer for the overall interest rate scenario in the economy. A well-functioning money market enhances the efficiency of capital allocation and strengthens the transmission mechanism of monetary policy.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'significance-capital-market-primary-secondary-markets' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37f-en-624","language":"English","title":"Capital Market: primary & secondary markets","topic_slug":"capital-market-primary-secondary-markets","definition":"Capital Market is a financial market where long-term securities such as shares, debentures, and bonds are issued and traded. It is divided into two segments: the primary market , where new securities are issued, and the secondary market , where existing securities are traded among investors. The primary market facilitates capital formation by allowing companies to raise funds from the public through Initial Public Offers (IPOs), rights issues, or private placements. In this market, securities are issued directly by the company to investors. The secondary market , on the other hand, provides liquidity by enabling investors to buy and sell existing securities on stock exchanges like BSE and NSE. It does not generate new capital but ensures marketability and price discovery. SEBI regulates both markets to ensure transparency and protect investor interests. The primary market is crucial for corporate growth, while the secondary market enhances investor confidence through tradability.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'capital-market-primary-secondary-markets' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37f-en-625","language":"English","title":"Financial Instruments: Treasury bills","topic_slug":"financial-instruments-treasury-bills","definition":"Treasury Bills (T-Bills) are short-term debt instruments issued by the Government of India to meet temporary cash requirements. They are zero-coupon securities, meaning they are issued at a discount and redeemed at face value. T-Bills are issued by the Reserve Bank of India on behalf of the government and are considered risk-free due to sovereign backing. They are available in three tenors: 91-day, 182-day, and 364-day. Since they do not pay interest, the return comes from the difference between the issue price and the redemption value. They are highly liquid and used by banks to meet their Statutory Liquidity Ratio (SLR) requirements. T-Bills are auctioned regularly by RBI and are accessible to banks, financial institutions, and individuals. They serve as a benchmark for short-term interest rates in the economy.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'financial-instruments-treasury-bills' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37f-en-626","language":"English","title":"CDs","topic_slug":"cds","definition":"Certificates of Deposit (CDs) are negotiable money market instruments issued by banks and financial institutions to raise short-term funds. They represent a time deposit with a fixed maturity and are issued at a discount to face value. CDs are issued by scheduled commercial banks and select all-India financial institutions. They have a minimum maturity of 7 days (for banks) and 1 year (for FIs). The minimum issue amount is ₹1 lakh, and they are freely transferable. CDs are unsecured but considered safe due to institutional credibility. They offer higher returns than savings accounts and are used by banks to meet credit demand without relying solely on deposits. Investors include corporations, trusts, and individuals seeking short-term investment options. CDs are regulated by the Reserve Bank of India under the Banking Regulation Act, 1949.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'cds' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37f-en-627","language":"English","title":"Commercial papers","topic_slug":"commercial-papers","definition":"Commercial Papers (CPs) are unsecured, short-term debt instruments issued by highly rated corporations, primary dealers, and financial institutions to raise working capital. They are a form of promissory note sold at a discount and redeemed at par. CPs are issued in denominations of ₹5 lakh and above, with maturities ranging from 7 days to up to 1 year. Only companies with a minimum credit rating of A-2 (by CRISIL, ICRA, etc.) can issue CPs, ensuring low default risk. They are issued in dematerialized form and traded in the secondary market. CPs offer a cost-effective alternative to bank loans for creditworthy firms. The Reserve Bank of India regulates CP issuance under the Money Market Instruments Guidelines. Investors include banks, mutual funds, and insurance companies seeking higher returns than T-Bills.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'commercial-papers' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37f-en-628","language":"English","title":"Call money","topic_slug":"call-money","definition":"Call Money refers to short-term funds borrowed and lent among banks on an overnight basis to meet temporary liquidity needs. It is a key component of the interbank money market. Call money is used primarily by commercial banks to maintain their Cash Reserve Ratio (CRR) requirements with the RBI. The borrowing and lending are uncollateralized and typically occur within a single day, though it can extend up to 14 days. The interest rate on call money, known as the call rate , is highly volatile and reflects the liquidity position in the banking system. Surplus banks lend to deficit banks through this market, coordinated via brokers or electronic platforms. The Reserve Bank of India monitors the call money market closely as it influences monetary policy transmission. It is restricted to scheduled commercial banks, co-operative banks, and primary dealers.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'call-money' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37f-en-629","language":"English","title":"Repos •","topic_slug":"repos","definition":"Repurchase Agreement (Repo) is a short-term borrowing instrument where securities (usually government bonds) are sold with an agreement to repurchase them at a predetermined price and date. It is a collateralized loan used in the money market. In a repo transaction, one party sells securities to another and agrees to buy them back at a higher price, with the difference representing interest (repo rate). Repos are used by banks and financial institutions to manage short-term liquidity. The Reserve Bank of India uses repos as a key monetary policy tool to inject liquidity into the system. A reverse repo is the opposite, where RBI absorbs excess liquidity by selling securities with a repurchase agreement. Repos reduce credit risk due to collateral, making them safer than call money. They are typically for 1 to 14 days and are conducted electronically via the RBI’s e-Kuber system.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'repos' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37f-en-630","language":"English","title":"Capital Market Instruments: Shares","topic_slug":"capital-market-instruments-shares","definition":"Shares represent ownership units in a company, entitling the holder to a portion of profits and voting rights in corporate decisions. They are issued by companies in the primary market and traded in the secondary market. When a company issues shares, it raises equity capital without creating a debt obligation. Shareholders are partial owners and may receive dividends if profits are declared. There are two main types: equity shares (with voting rights and variable returns) and preference shares (fixed dividend, no voting rights). Equity shareholders bear higher risk but have potential for higher returns through capital appreciation. Shares are listed on stock exchanges like BSE and NSE and traded electronically. The value of shares fluctuates based on company performance, market sentiment, and economic conditions.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'capital-market-instruments-shares' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37f-en-631","language":"English","title":"Debentures","topic_slug":"debentures","definition":"Debentures are debt instruments issued by companies to raise long-term funds, acknowledging a loan with a promise to repay principal and interest. They are unsecured or secured and represent borrowed capital. Debenture holders are creditors of the company and receive fixed interest at regular intervals. Unlike shares, debentures do not confer ownership or voting rights. They may be secured (backed by company assets) or unsecured (no collateral). Convertible debentures can be converted into equity shares after a specified period, offering hybrid features. Non-convertible debentures (NCDs) remain as debt throughout. Debentures are rated by credit agencies to assess default risk. They are issued in the primary market and traded in the secondary market, regulated by SEBI.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'debentures' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37f-en-632","language":"English","title":"Bonds","topic_slug":"bonds","definition":"Bonds are long-term debt securities issued by governments, municipalities, or corporations to raise capital, with a promise to repay the principal along with periodic interest. They are a key instrument in the capital market. Government bonds, such as G-Secs (Government Securities), are issued by the Central or State governments and are considered risk-free. Corporate bonds are issued by companies and carry higher risk but offer higher yields. Bonds have a fixed maturity date and pay interest (coupon) at regular intervals. They are issued at par, premium, or discount and traded in the secondary market. Investors include banks, insurance companies, and mutual funds seeking stable returns. Bonds help in infrastructure financing and monetary policy implementation.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'bonds' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37f-en-633","language":"English","title":"Mutual Funds","topic_slug":"mutual-funds","definition":"Mutual Funds are investment vehicles that pool money from multiple investors to invest in a diversified portfolio of securities such as shares, bonds, and money market instruments. They are managed by professional fund managers. Mutual funds offer small investors access to diversified, professionally managed portfolios. Units are issued to investors based on the Net Asset Value (NAV), which is calculated daily. Funds are categorized by asset class: equity funds , debt funds , hybrid funds , and index funds . They can be open-ended (units bought/sold anytime) or closed-ended (fixed tenure). Returns come from dividends, interest, and capital appreciation. The Securities and Exchange Board of India (SEBI) regulates mutual funds under the SEBI (Mutual Funds) Regulations, 1996.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'mutual-funds' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37f-en-634","language":"English","title":"Derivatives","topic_slug":"derivatives","definition":"Derivatives are financial contracts whose value is derived from an underlying asset such as shares, bonds, commodities, or indices. They are used for hedging risk, speculation, and arbitrage. Common types of derivatives include futures , options , forwards , and swaps . A futures contract is a standardized agreement to buy or sell an asset at a future date at a predetermined price. An option gives the buyer the right, but not the obligation, to buy (call) or sell (put) the asset. Derivatives are traded on exchanges (e.g., NSE, BSE) or over-the-counter (OTC). They help investors manage price risk in volatile markets. In India, derivatives trading is regulated by SEBI and primarily takes place in stock and commodity exchanges.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'derivatives' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de38b-en-635","language":"English","title":"Banking institutions: types","topic_slug":"banking-institutions-types","definition":"Banking institutions are financial entities licensed to accept deposits, provide loans, and offer various financial services to individuals and businesses. They play a central role in the financial system by mobilizing savings and channeling them into productive investments. Banking institutions in India are primarily classified into Scheduled Banks and Non-Scheduled Banks , with Scheduled Banks listed in the Second Schedule of the Reserve Bank of India Act, 1934. Scheduled Banks are further divided into Commercial Banks , Cooperative Banks , and Regional Rural Banks (RRBs) . Commercial Banks include Public Sector Banks (PSBs) like State Bank of India, Private Sector Banks like HDFC Bank, and Foreign Banks like Standard Chartered. Cooperative Banks operate at state, district, and local levels, primarily serving agricultural and rural sectors. Regional Rural Banks were established under the Regional Rural Banks Act, 1976 to provide credit to rural and agricultural populations.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de38b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'banking-institutions-types' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de38b-en-636","language":"English","title":"functions","topic_slug":"functions","definition":"Functions of banking institutions refer to the core activities they perform to facilitate financial intermediation and support economic activity. These functions are essential for maintaining liquidity, encouraging savings, and enabling investment across sectors. The primary functions of banks include acceptance of deposits , granting loans and advances , and credit creation . Banks accept deposits in various forms—savings, current, and fixed deposits—and offer interest to depositors. They lend money through cash credits, overdrafts, term loans, and bill discounting, earning interest income. Banks also perform secondary functions such as cheque collection, fund transfers, locker services, and issuance of letters of credit. Additionally, modern banks offer agency services (e.g., bill payments, share trading) and general utility services (e.g., underwriting, advisory). These functions collectively enhance financial efficiency, promote savings culture, and support business operations and economic growth.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de38b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'functions' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de38b-en-637","language":"English","title":"structure of Indian banking •","topic_slug":"structure-of-indian-banking","definition":"Structure of Indian banking refers to the hierarchical and functional organization of banking institutions regulated by the Reserve Bank of India (RBI) and governed by statutory frameworks. It reflects the classification and interrelationship among various types of banks operating in the country. The Indian banking structure is broadly divided into the Reserve Bank of India (RBI) at the apex, followed by Commercial Banks , Cooperative Banks , and Specialized Financial Institutions . Commercial Banks are categorized into Public Sector Banks (PSBs), Private Sector Banks, and Foreign Banks. Cooperative Banks are organized in a three-tier system: State Cooperative Banks (SCBs) at the top, District Central Cooperative Banks (DCCBs) in the middle, and Primary Agricultural Credit Societies (PACS) at the grassroots level. Regional Rural Banks (RRBs) operate under the sponsorship of PSBs and are regulated jointly by the RBI and NABARD.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de38b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'structure-of-indian-banking' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de38b-en-638","language":"English","title":"Non-banking institutions: types","topic_slug":"non-banking-institutions-types","definition":"Non-banking institutions are financial entities that provide financial services but do not hold banking licenses and cannot accept demand deposits. They play a complementary role to banks by offering specialized financial products and services. These institutions include Mutual Funds , Insurance Companies , Pension Funds , Non-Banking Financial Companies (NBFCs) , and Venture Capital Funds . NBFCs are registered under the Companies Act and regulated by the RBI' || char(59) || ' they offer loans, leasing, and hire-purchase services. Insurance companies like LIC and private insurers provide life and general insurance products. Mutual Funds pool investor money to invest in securities, managed by Asset Management Companies (AMCs). Pension Funds, such as the National Pension System (NPS), manage retirement savings. These institutions enhance financial deepening by catering to diverse needs such as investment, risk protection, and long-term savings, thereby supporting capital market development.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de38b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'non-banking-institutions-types' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de38b-en-639","language":"English","title":"structure •","topic_slug":"structure","definition":"Structure of non-banking financial institutions refers to their organizational framework, regulatory oversight, and operational hierarchy within the Indian financial system. These institutions function under specific regulatory bodies and are structured to serve niche financial needs. The structure is defined by the type of institution and its regulatory authority. NBFCs are classified by the RBI into categories such as Asset Finance Companies, Investment Companies, and Loan Companies, based on their primary activity. Insurance companies are regulated by the Insurance Regulatory and Development Authority of India (IRDAI), established in 1999. Pension Funds operate under the National Pension System (NPS) and are supervised by the Pension Fund Regulatory and Development Authority (PFRDA), set up in 2013. Mutual Funds are governed by SEBI (Mutual Funds) Regulations, 1996, and structured as trusts with sponsors, trustees, and Asset Management Companies (AMCs).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de38b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'structure' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de38b-en-640","language":"English","title":"Mutual Funds","topic_slug":"mutual-funds","definition":"Mutual Funds are investment vehicles that pool money from multiple investors to invest in a diversified portfolio of securities such as stocks, bonds, and money market instruments. They are managed by professional fund managers employed by Asset Management Companies (AMCs). Mutual Funds offer an accessible way for individual investors to participate in financial markets with limited capital. They operate under a trust structure regulated by SEBI (Mutual Funds) Regulations, 1996. Based on investment objectives, they are classified into equity funds , debt funds , hybrid funds , and solution-oriented funds like retirement or children’s plans. Investors earn returns through dividends, interest, or capital appreciation, and units are bought or sold at the Net Asset Value (NAV). Mutual Funds promote financial inclusion, diversification, and professional management, making them popular among retail investors. Their growth has been significant since the entry of private and foreign players post-1991 liberalization.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de38b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'mutual-funds' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de38b-en-641","language":"English","title":"Insurance Companies","topic_slug":"insurance-companies","definition":"Insurance Companies are financial institutions that provide risk coverage by pooling premiums from policyholders and compensating them for specified losses. They operate on the principle of risk pooling and indemnity, offering financial protection against uncertain events. These companies are broadly classified into Life Insurance Companies and General (Non-Life) Insurance Companies . Life insurers, such as Life Insurance Corporation (LIC) and private players like HDFC Life, provide policies for death, survival, and retirement benefits. General insurers, including ICICI Lombard and New India Assurance, cover risks related to health, property, vehicles, and liability. The industry was nationalized in 1956 with the formation of LIC, and later liberalized in 2000 with the entry of private and foreign insurers under IRDAI regulations. Insurance companies invest premiums in government securities, corporate bonds, and equities to generate returns while maintaining solvency. They play a vital role in financial stability, risk mitigation, and long-term savings mobilization.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de38b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'insurance-companies' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de38b-en-642","language":"English","title":"Pension Funds","topic_slug":"pension-funds","definition":"Pension Funds are financial institutions that collect, pool, and invest contributions from individuals and employers to provide retirement benefits. They ensure income security during post-employment years through long-term investment strategies. In India, the primary pension system is the National Pension System (NPS) , introduced in 2004 for government employees and extended to all citizens in 2009. It is a defined-contribution scheme where individuals contribute regularly to a pension account, and the corpus grows through market-linked investments. The Pension Fund Regulatory and Development Authority (PFRDA) regulates NPS and oversees Pension Fund Managers (PFMs) like SBI Pension Funds and HDFC Pension. Contributions are invested across asset classes—equity, corporate bonds, and government securities—based on the subscriber’s risk profile. At retirement, a portion of the corpus is used to buy an annuity, ensuring regular income. Pension Funds promote long-term savings and reduce dependency on family or state in old age.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de38b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'pension-funds' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de38b-en-643","language":"English","title":"Financial Services: Factoring","topic_slug":"financial-services-factoring","definition":"Factoring is a financial service where a firm sells its accounts receivable (invoices) to a third party (factor) at a discount to obtain immediate cash. It helps businesses improve cash flow and manage credit risk. In factoring, the factor assumes responsibility for collecting payments from debtors and may provide additional services like credit assessment and ledger management. It is commonly used by small and medium enterprises (SMEs) with irregular cash flows. The process involves three parties: the seller (client), the buyer (debtor), and the factor. Factoring can be with recourse (client bears risk of default) or without recourse (factor bears default risk at higher cost). This service reduces the burden of collection, enhances liquidity, and supports business expansion. In India, factoring is regulated under the Factoring Regulation Act, 2011, and offered by banks and specialized NBFCs.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de38b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'financial-services-factoring' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de38b-en-644","language":"English","title":"Leasing","topic_slug":"leasing","definition":"Leasing is a financial service that allows an individual or business to use an asset for a specified period in exchange for periodic payments, without owning it. It is an alternative to purchasing assets, especially for capital-intensive equipment. In a lease agreement, the lessor (owner) grants the lessee (user) the right to use the asset, such as machinery, vehicles, or real estate. Leasing is classified into operating lease (short-term, lessor maintains asset) and financial lease (long-term, lessee bears maintenance and risks). It benefits businesses by conserving capital, avoiding obsolescence, and enabling access to modern technology. Leasing companies, often NBFCs, purchase the asset and lease it out, earning income through lease rentals. In India, leasing is regulated by the RBI for NBFCs and governed by the Indian Contract Act, 1872. It supports industrial growth and asset utilization without heavy upfront investment.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de38b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'leasing' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de38b-en-645","language":"English","title":"Venture Capital","topic_slug":"venture-capital","definition":"Venture Capital is a form of private equity financing provided to early-stage, high-potential, and high-risk startups or small businesses. It involves investment in exchange for equity ownership, aiming for high returns through capital appreciation. Venture capitalists (VCs) invest in innovative ventures, particularly in technology, biotechnology, and e-commerce sectors, where traditional financing is unavailable. The investment process includes due diligence, valuation, equity stake negotiation, and active involvement in business strategy. Venture Capital funds are typically structured as closed-end funds with a lifespan of 7–10 years. Investors include institutional investors, high-net-worth individuals, and government-backed funds like SIDBI. In India, the venture capital industry grew significantly post-1990s liberalization, supported by SEBI (Venture Capital Funds) Regulations, 1996. It plays a crucial role in fostering innovation, entrepreneurship, and job creation.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de38b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'venture-capital' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de38b-en-646","language":"English","title":"Consumer finance","topic_slug":"consumer-finance","definition":"Consumer finance refers to financial services that provide credit to individuals for purchasing durable goods or services such as electronics, furniture, and personal appliances. It enables consumers to make purchases without immediate full payment. Consumer finance is typically offered through personal loans , credit cards , point-of-sale financing , and hire-purchase agreements . It is provided by banks, NBFCs, and specialized finance companies like Bajaj Finance and Home Credit. The credit is unsecured or secured against the purchased item, with interest charged on the outstanding amount. Lenders assess creditworthiness using credit scores, income, and repayment history. This service boosts consumption, drives demand for goods, and supports economic growth. In India, consumer finance has expanded rapidly due to rising disposable incomes and digital lending platforms.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de38b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'consumer-finance' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de38b-en-647","language":"English","title":"Housing finance","topic_slug":"housing-finance","definition":"Housing finance is a financial service that provides loans to individuals for purchasing, constructing, or renovating residential properties. It plays a critical role in promoting homeownership and urban development. Housing loans are offered by Housing Finance Companies (HFCs) and banks, with repayment over long tenures (5–30 years) through equated monthly installments (EMIs). The loan amount depends on factors like income, credit history, property value, and interest rates. HFCs such as HDFC (before merger), LIC Housing Finance, and PNB Housing Finance specialize in this sector. These institutions are regulated by the National Housing Bank (NHB), established in 1988 under the National Housing Bank Act, 1987. Housing finance stimulates construction activity, generates employment, and contributes to GDP growth. Government schemes like Pradhan Mantri Awas Yojana (PMAY) further support affordable housing finance.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de38b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'housing-finance' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de38a-en-648","language":"English","title":"Types of Pramanas","topic_slug":"types-of-pramanas","definition":"Pratyaksha (Perception) : Direct sensory knowledge. It must be indriya-artha-sannikarsha (contact between sense organ and object), free from illusion. E.g., seeing fire on a hill. 2. Anumana (Inference) : Knowledge derived from a sign ( linga ) and a universal relation ( vyapti ). E.g., inferring fire from smoke (\"Where there is smoke, there is fire\"). 3. Upamana (Comparison) : Knowledge from similarity. E.g., learning \"a gavaya is like a cow\" and later identifying it. 4. Shabda (Verbal Testimony) : Reliable verbal communication, especially from āpta (trustworthy persons) or scriptures. Vedic statements are shabda pramana for orthodox schools. 5. Arthapatti (Postulation) : Deriving truth from circumstantial implication. E.g., \"Devadatta is fat but does not eat during the day\" → he must eat at night. 6. Anupalabdhi (Non-apprehension) : Knowledge from absence. E.g., knowing there is no pot on the table by not perceiving it.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de38a' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'types-of-pramanas' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35e-en-649","language":"English","title":"Legal and Regulatory Compliance","topic_slug":"legal-and-regulatory-compliance","definition":"Ensuring that office practices follow labor laws, data protection rules (like the Digital Personal Data Protection Act, 2023), and organizational policies is a critical responsibility. The importance of office management cannot be overstated. First, it ensures efficiency —tasks are completed faster with fewer errors. Second, it supports decision-making by providing accurate data and reports. Third, it enhances coordination between departments. Fourth, it improves public and client service , especially in government and service-sector offices. Fifth, it contributes to cost control by preventing waste of resources. Sixth, it ensures continuity of operations even during staff changes or emergencies. Seventh, it promotes professionalism and discipline in the workplace. In Assam, where many offices still transition from manual to digital systems, effective office management is key to reducing corruption, delays, and inefficiencies in public service delivery.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35e' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'legal-and-regulatory-compliance' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35e-en-650","language":"English","title":"Primary (Operational) Functions","topic_slug":"primary-operational-functions","definition":"These are day-to-day tasks that keep the office running: 1. Receiving and Recording Information This includes incoming mail, emails, phone calls, and visitor logs. For example, in a college office in Silchar, applications for admission are received and logged systematically. 2. Processing and Classifying Data Raw information is sorted, categorized, and prepared for use. Student marksheets, for instance, are processed and classified by department and semester. 3. Storing and Filing Records Both physical and digital filing systems are used. In a bank branch in Tinsukia, customer account records are stored securely for future reference. 4. Reproducing and Distributing Information Reports, notices, and circulars are copied and sent to concerned departments or individuals. A municipal office in Dhubri may distribute sanitation schedules to ward officers. 5. Handling Correspondence Drafting, editing, and dispatching official letters—both internal and external—is a key function. Government offices use standardized formats for official communication. 6.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35e' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'primary-operational-functions' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35e-en-651","language":"English","title":"Administrative (Managerial) Functions","topic_slug":"administrative-managerial-functions","definition":"These are higher-level functions performed by office managers: 1. Planning Deciding in advance what needs to be done, how, and by whom. For example, planning the annual budget for office supplies. 2. Organizing Arranging resources—staff, equipment, space—into a structured system. This includes creating job descriptions and workflow charts. 3. Staffing Recruiting, training, and supervising office personnel. In a private hospital in Jorhat, the office manager may hire data entry operators. 4. Directing Leading and motivating staff, giving instructions, and ensuring work is completed. This involves daily supervision and feedback. 5. Controlling Monitoring performance, comparing it with standards, and taking corrective action. For instance, checking if filing is up to date or if response times to queries are acceptable. These functions are interdependent. While primary functions ensure daily operations, administrative functions ensure long-term efficiency and alignment with organizational goals.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35e' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'administrative-managerial-functions' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35e-en-652","language":"English","title":"Responsibilities of an Office Manager","topic_slug":"responsibilities-of-an-office-manager","definition":"Overseeing Daily Operations Ensuring that all office activities—reception, filing, correspondence, and communication—are carried out efficiently. 2. Managing Office Supplies and Equipment Procuring stationery, maintaining computers, printers, and other tools, and ensuring timely repairs. 3. Supervising Staff Assigning tasks, monitoring performance, and providing guidance to clerks, typists, and assistants. 4. Maintaining Records and Files Ensuring both physical and digital records are updated, secure, and retrievable. 5. Handling Correspondence Drafting, reviewing, and dispatching official letters, emails, and reports. 6. Coordinating Meetings and Appointments Scheduling meetings, preparing agendas, and arranging logistics like rooms and refreshments. 7. Implementing Office Policies Enforcing rules on attendance, dress code, data security, and conduct. 8. Budget Management Preparing and monitoring the office budget for expenses like travel, supplies, and maintenance. 9. Ensuring Compliance Adhering to organizational, legal, and safety regulations, including data protection laws. 10.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35e' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'responsibilities-of-an-office-manager' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35e-en-653","language":"English","title":"Qualities of a Successful Office Manager","topic_slug":"qualities-of-a-successful-office-manager","definition":"Organizational Skills Ability to plan, prioritize, and manage multiple tasks efficiently. 2. Communication Skills Clear, polite, and professional interaction with staff, superiors, and visitors. 3. Leadership and Motivation Inspiring team members and resolving conflicts. 4. Technical Proficiency Familiarity with MS Office, email, ERP systems, and digital filing. 5. Integrity and Confidentiality Handling sensitive information (e.g., employee records) with discretion. 6. Problem-Solving Ability Quick thinking to resolve issues like equipment failure or staff disputes. 7. Time Management Meeting deadlines and ensuring punctuality in all office functions. 8. Adaptability Adjusting to new technologies, policies, or work environments. 9. Attention to Detail Ensuring accuracy in records, reports, and correspondence. 10. Professionalism Maintaining decorum, discipline, and a positive work culture. In Assam, where many offices are transitioning to e-governance, office managers with digital literacy and leadership skills are in high demand.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35e' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'qualities-of-a-successful-office-manager' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35e-en-654","language":"English","title":"Key Functions of Front Office","topic_slug":"key-functions-of-front-office","definition":"Reception and Greeting Welcoming visitors, answering queries, and directing them to the appropriate person or department. 2. Information Dissemination Providing details about services, procedures, forms, and requirements. For example, in a passport office in Guwahati, staff guide applicants through the process. 3. Appointment Scheduling Managing calendars, booking slots, and sending reminders. 4. Handling Complaints and Feedback Listening to customer concerns and escalating them when necessary. 5. Maintaining Visitor Logs Recording names, purposes of visits, and entry/exit times for security and record-keeping. 6. Telephone and Email Management Answering calls, forwarding messages, and responding to basic inquiries. 7. Document Collection Receiving applications, forms, and supporting documents from clients. 8. Public Relations Representing the organization in a courteous and professional manner. The front office is often staffed by receptionists, customer service executives, or clerks trained in communication and etiquette. In hotels, the front office includes the front desk, concierge, and reservation staff.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35e' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'key-functions-of-front-office' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35e-en-655","language":"English","title":"Key Functions of Back Office","topic_slug":"key-functions-of-back-office","definition":"Data Processing and Entry Inputting and managing customer or employee data into databases. For example, entering student marks in a university office. 2. Accounting and Payroll Managing salaries, taxes, invoices, and financial records. In a tea estate office in Dibrugarh, payroll processing for thousands of workers is a back office task. 3. Record Keeping and Archiving Maintaining historical files, both physical and digital, for compliance and reference. 4. IT and Technical Support Managing servers, networks, software updates, and troubleshooting. This is critical in digital offices. 5. Human Resource Administration Processing leave applications, attendance records, and employee files. 6. Inventory and Supply Management Tracking office supplies, equipment, and consumables. 7. Compliance and Audit Support Preparing documents for internal and external audits, ensuring adherence to laws. 8. Report Generation Creating performance, financial, or operational reports for management.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35e' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'key-functions-of-back-office' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35e-en-656","language":"English","title":"Features of a Virtual Office","topic_slug":"features-of-a-virtual-office","definition":"Remote Work Employees work from home, co-working spaces, or any location with internet access. 2. Digital Communication Tools Use of email, video conferencing (Zoom, Google Meet), instant messaging (Slack, WhatsApp), and collaboration platforms (Google Workspace, Microsoft Teams). 3. Cloud-Based Data Storage Files and records are stored on cloud services like Google Drive, Dropbox, or OneDrive, accessible from anywhere. 4. Virtual Phone Systems Calls are routed through VoIP (Voice over Internet Protocol) services, allowing receptionists to answer calls remotely. 5. Project Management Software Tools like Trello, Asana, or Notion help track tasks, deadlines, and team progress. 6. Cybersecurity Measures Use of firewalls, encryption, and two-factor authentication to protect data. 7. Flexible Work Hours Employees may work in shifts or according to their productivity cycles, as long as tasks are completed.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35e' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'features-of-a-virtual-office' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35e-en-657","language":"English","title":"Advantages","topic_slug":"advantages","definition":"Cost Savings : No need for large office spaces, furniture, or utilities. Flexibility : Employees can balance work and personal life better. Wider Talent Pool : Organizations can hire skilled workers from anywhere, including rural Assam. Business Continuity : Operations continue during floods, strikes, or pandemics.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35e' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'advantages' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35e-en-658","language":"English","title":"Challenges","topic_slug":"challenges","definition":"Lack of Supervision : Managers may find it hard to monitor performance. Communication Gaps : Delayed responses or misunderstandings can occur. Data Security Risks : Unsecured networks may lead to data breaches. Isolation : Remote workers may feel disconnected from the team. In Assam, virtual offices are increasingly used by startups, freelancers, and government e-governance projects. For example, during the 2020 lockdown, many district offices in Assam adopted virtual workflows for processing relief applications.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35e' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'challenges' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de374-en-659","language":"English","title":"Management: concept and importance' || char(59) || ' Classical theories: Scientific Management","topic_slug":"management-concept-and-importance-classical-theories-scientific-management","definition":"Management is the process of planning, organizing, leading, and controlling resources—such as people, money, materials, and time—to achieve organizational goals efficiently and effectively. It is essential in all types of organizations, whether business, educational, or governmental. Management ensures that resources are used optimally to meet objectives, reduces waste, and improves productivity. It involves decision-making, coordination, and supervision at various levels of an organization. One of the earliest formal approaches to management is Scientific Management , developed by Frederick W. Taylor in the early 20th century. This theory emphasized using scientific methods to determine the best way to perform tasks, standardizing work processes, and offering financial incentives for increased output. It marked a shift from traditional rule-of-thumb methods to systematic analysis of work. Scientific Management improved industrial efficiency but was criticized for treating workers like machines and ignoring human needs.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de374' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'management-concept-and-importance-classical-theories-scientific-management' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de374-en-660","language":"English","title":"General theory of Administration - an overview","topic_slug":"general-theory-of-administration-an-overview","definition":"General Administrative Theory is a classical management theory that focuses on the overall functioning of the organization and the principles that guide managerial actions at the administrative level. Unlike Scientific Management, which focuses on shop-floor operations, this theory addresses higher-level management functions and organizational structure. Developed primarily by Henri Fayol , a French mining engineer and manager, this theory outlines universal principles applicable to all organizations. Fayol identified 14 Principles of Management , such as unity of command , scalar chain , division of work , and esprit de corps . He also defined five key functions of management: planning, organizing, commanding, coordinating, and controlling —which form the foundation of modern management functions. Fayol’s approach was top-down, emphasizing organizational structure, authority, and administrative efficiency. His work laid the groundwork for understanding management as a distinct discipline separate from technical operations.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de374' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'general-theory-of-administration-an-overview' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de374-en-661","language":"English","title":"Hawthorne experiment","topic_slug":"hawthorne-experiment","definition":"Hawthorne Experiments were a series of studies conducted between 1924 and 1932 at the Western Electric Hawthorne Works plant in Chicago to examine the impact of physical working conditions on worker productivity. Initially designed to study the effects of lighting on efficiency, the experiments unexpectedly revealed that social and psychological factors had a greater influence on performance. The studies were conducted in phases: the Illumination Experiments , Relay Assembly Test Room , Interview Program , and Bank Wiring Observation Room . Researchers, including Elton Mayo , Fritz Roethlisberger , and William Dickson , found that productivity increased regardless of whether lighting was improved or worsened. The key insight was that workers performed better because they felt observed and valued—a phenomenon later termed the Hawthorne Effect . The experiments highlighted the importance of group dynamics, informal work groups, supervision style, and employee recognition.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de374' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'hawthorne-experiment' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de374-en-662","language":"English","title":"human relations movement and behavioural movement - an overview.","topic_slug":"human-relations-movement-and-behavioural-movement-an-overview","definition":"Human Relations Movement is a management approach that emphasizes the importance of social and psychological factors in the workplace, such as employee motivation, group dynamics, and leadership style. It emerged from the findings of the Hawthorne Experiments and marked a shift from mechanistic views of workers to recognizing them as social beings. Led by Elton Mayo and Fritz Roethlisberger , this movement argued that employee satisfaction and interpersonal relationships directly affect productivity. It highlighted that workers are motivated not only by money but also by recognition, job security, and a sense of belonging. The Behavioural Movement expanded on this by applying psychology and sociology to understand individual and group behavior in organizations. It introduced concepts like participative management , leadership styles , and motivation theories (e.g., Maslow’s Hierarchy of Needs). Together, these movements laid the foundation for modern organizational behavior and human resource management.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de374' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'human-relations-movement-and-behavioural-movement-an-overview' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de374-en-663","language":"English","title":"(b) Contemporary Management theories: Management by Objectives (MbO) by Peter F. Drucker","topic_slug":"b-contemporary-management-theories-management-by-objectives-mbo-by-peter-f-drucker","definition":"Management by Objectives (MBO) is a strategic management model introduced by Peter F. Drucker in his 1954 book The Practice of Management , where managers and employees collaboratively set specific, measurable goals to improve organizational performance. It emphasizes goal-setting, participative decision-making, and performance evaluation based on achieved results. In MBO, objectives are established at all levels of the organization, aligning individual goals with overall organizational aims. The process involves five key steps: goal setting , planning , implementation , performance review , and feedback . Employees are more motivated when they participate in setting their own goals, leading to greater accountability and clarity. MBO promotes a results-oriented culture and helps in monitoring progress systematically. However, it can be time-consuming and may fail if goals are poorly defined or if there is lack of commitment from management.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de374' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'b-contemporary-management-theories-management-by-objectives-mbo-by-peter-f-drucker' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de374-en-664","language":"English","title":"Mary Parker Follet''s theory of Management","topic_slug":"mary-parker-follet-s-theory-of-management","definition":"Mary Parker Follet’s theory of Management emphasizes the importance of human relations, group dynamics, and participative leadership in organizations. She advocated for a democratic and integrative approach to management, where power is shared, and conflicts are resolved through collaboration rather than domination. Follet believed that organizations should function as communities where employees cooperate and contribute ideas. She introduced the concept of \"power with\" instead of \"power over\" , promoting shared authority and mutual influence. She viewed conflict as a natural and potentially constructive force, best resolved through integration —finding solutions that satisfy all parties. Follet also emphasized situation-based leadership , where leaders adapt to circumstances rather than rely on hierarchical authority. Her ideas were ahead of her time and laid the groundwork for modern concepts like teamwork, empowerment, and transformational leadership.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de374' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'mary-parker-follet-s-theory-of-management' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de374-en-665","language":"English","title":"Managerial roles by Henry Mintzberg.","topic_slug":"managerial-roles-by-henry-mintzberg","definition":"Managerial roles by Henry Mintzberg refer to a framework developed in the 1970s that categorizes the actual activities performed by managers into ten distinct roles, grouped under three main types: interpersonal, informational, and decisional . Based on empirical observation of five chief executives, Mintzberg challenged traditional functional views of management by showing what managers actually do on the job. The interpersonal roles include Figurehead, Leader, and Liaison , involving duties of ceremony, motivation, and external networking. The informational roles — Monitor, Disseminator, and Spokesperson —relate to gathering, sharing, and transmitting information. The decisional roles — Entrepreneur, Disturbance Handler, Resource Allocator, and Negotiator —involve making strategic choices, managing crises, distributing resources, and bargaining. Mintzberg’s model is based on real-world observation rather than theoretical assumptions, making it highly practical. It helps in understanding the complexity and fragmented nature of managerial work, which often involves short tasks and rapid shifts in focus.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de374' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'managerial-roles-by-henry-mintzberg' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de387-en-666","language":"English","title":"Planning Premises and Elements","topic_slug":"planning-premises-and-elements","definition":"Planning premises are the assumptions about future conditions and events that are considered while formulating plans. These premises serve as the foundation upon which plans are built and help managers anticipate changes and uncertainties. Effective planning requires reliable premises that reflect economic, political, social, technological, and competitive environments. Planning premises can be classified into external and internal, tangible and intangible, and controllable and non-controllable categories. External premises include government policies, market trends, and technological changes, while internal premises involve organizational resources, employee skills, and management philosophy. Tangible premises are quantifiable, such as budget figures or sales forecasts, whereas intangible ones include employee morale or brand reputation. Accurate identification and analysis of these premises enhance the validity and success of plans. Without sound premises, even well-designed plans may fail due to unrealistic assumptions.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de387' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'planning-premises-and-elements' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de387-en-667","language":"English","title":"Limitations of planning - Environmental analysis and SWOT analysis","topic_slug":"limitations-of-planning-environmental-analysis-and-swot-analysis","definition":"Limitations of planning refer to the constraints and challenges that reduce the effectiveness of planning in dynamic environments. Despite its importance, planning often fails due to uncertainties, rigidity, high costs, and rapid environmental changes. Environmental analysis is the process of monitoring external factors—such as political, economic, social, technological, legal, and environmental (PESTLE) forces—that impact organizational performance. It helps organizations anticipate changes and formulate adaptive strategies. However, inaccurate forecasts or incomplete data can lead to flawed planning. One widely used tool in environmental analysis is SWOT analysis , which evaluates an organization’s Strengths , Weaknesses , Opportunities , and Threats . Strengths and weaknesses are internal factors, while opportunities and threats are external. SWOT analysis enables managers to align internal capabilities with external conditions for strategic advantage. Yet, planning remains limited by unforeseen events, resistance to change, and over-reliance on historical data.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de387' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'limitations-of-planning-environmental-analysis-and-swot-analysis' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3a9-en-668","language":"English","title":"(a) Motivation: meaning","topic_slug":"a-motivation-meaning","definition":"Motivation is the internal process that drives individuals to take action towards achieving a goal. It is the psychological force that initiates, guides, and sustains goal-oriented behaviors in individuals. Motivation arises from both intrinsic factors (such as personal growth, interest, or passion) and extrinsic factors (like rewards, recognition, or punishment). It determines the direction, intensity, and persistence of behavior. In an organizational context, motivation influences employee performance, productivity, and job satisfaction. When employees are motivated, they are more likely to contribute positively to organizational goals. The absence of motivation can lead to low morale, absenteeism, and high turnover. Understanding motivation is essential for managers to create an environment that encourages commitment and high performance.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3a9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'a-motivation-meaning' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3a9-en-669","language":"English","title":"importance' || char(59) || ' Motivation theory: Maslow''s theory","topic_slug":"importance-motivation-theory-maslow-s-theory","definition":"Maslow''s Hierarchy of Needs Theory is a motivational theory in psychology that proposes that humans are motivated by a five-tier hierarchy of needs, ranging from basic physiological needs to self-actualization. Abraham Maslow introduced this theory in 1943 in his paper \"A Theory of Human Motivation.\" The five levels of needs are: physiological (food, water), safety (security, stability), social (love, belonging), esteem (recognition, respect), and self-actualization (achieving one’s full potential). According to Maslow, lower-level needs must be satisfied before higher-level needs become motivators. For example, a person struggling to meet basic food needs will not be primarily concerned with gaining respect at work. Managers can use this theory to understand employee behavior and design appropriate motivational strategies. By identifying which level of need an employee is currently seeking to fulfill, leaders can offer relevant incentives. This theory emphasizes that motivation is dynamic and changes as needs evolve.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3a9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'importance-motivation-theory-maslow-s-theory' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3a9-en-670","language":"English","title":"Equity theory","topic_slug":"equity-theory","definition":"Equity Theory , developed by J. Stacy Adams in 1963, suggests that employees are motivated by fairness and compare their input-output ratio with that of others. Employees assess whether they are being treated fairly by comparing their own contributions (inputs) such as effort, skills, and time, with the rewards they receive (outputs) like salary, recognition, and benefits. They then compare this ratio with that of a referent—another person or group in a similar position. If they perceive an imbalance—either under-rewarded or over-rewarded—tension arises, leading to demotivation or guilt. To restore equity, individuals may alter their inputs, demand more outputs, or change their perception of the situation. Managers must ensure fair distribution of rewards to maintain motivation and morale. Perceived inequity can lead to reduced productivity, absenteeism, or employee turnover.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3a9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'equity-theory' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3a9-en-671","language":"English","title":"McGregor''s theory X and Y","topic_slug":"mcgregor-s-theory-x-and-y","definition":"McGregor''s Theory X and Theory Y are two contrasting models of human motivation and management developed by Douglas McGregor in 1960, reflecting different managerial attitudes toward employees. Theory X assumes that employees are inherently lazy, avoid responsibility, and need to be closely supervised and controlled to perform effectively. Managers using this approach rely on coercion, threats, and centralized authority. In contrast, Theory Y assumes that employees are self-motivated, enjoy work, seek responsibility, and are capable of innovation. Managers following Theory Y encourage participation, decentralization, and trust. McGregor believed that Theory Y was more effective in fostering motivation and productivity in modern organizations. The theory highlights how managerial assumptions directly influence leadership style and organizational culture. It encourages managers to adopt a positive view of human nature to unlock employee potential.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3a9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'mcgregor-s-theory-x-and-y' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3a9-en-672","language":"English","title":"two factor theory","topic_slug":"two-factor-theory","definition":"Two-Factor Theory , also known as Herzberg’s Motivation-Hygiene Theory, was developed by Frederick Herzberg in the 1950s to explain job satisfaction and dissatisfaction. Herzberg identified two sets of factors affecting employee motivation: hygiene factors and motivators. Hygiene factors (such as salary, job security, working conditions, company policies, and supervision) do not motivate when present but cause dissatisfaction when absent. Motivators (such as achievement, recognition, responsibility, advancement, and growth) lead to job satisfaction and increased motivation. The theory suggests that to motivate employees, managers must first ensure hygiene factors are adequate to prevent dissatisfaction, then focus on motivators to enhance satisfaction. Unlike traditional views, Herzberg argued that satisfaction is not the opposite of dissatisfaction but results from different factors. This theory supports job enrichment and redesign to enhance motivation.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3a9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'two-factor-theory' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3a9-en-673","language":"English","title":"Goal setting theory","topic_slug":"goal-setting-theory","definition":"Goal Setting Theory , developed by Edwin Locke in 1968, states that specific and challenging goals lead to higher performance than easy or vague goals. According to this theory, clear and well-defined goals direct attention, increase effort, and enhance persistence. Goals that are difficult but achievable motivate individuals more than easy goals because they require greater effort and provide a sense of accomplishment. Feedback is a critical component, as it helps individuals track progress and adjust behavior. The theory also emphasizes that goal commitment, self-efficacy, and task complexity influence the effectiveness of goal setting. Managers can apply this theory by setting SMART goals (Specific, Measurable, Achievable, Relevant, Time-bound) and involving employees in the goal-setting process. This approach enhances motivation, accountability, and performance in organizations.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3a9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'goal-setting-theory' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3a9-en-674","language":"English","title":"McClelland''s Needs theory. (b) Leadership: meaning","topic_slug":"mcclelland-s-needs-theory-b-leadership-meaning","definition":"McClelland''s Needs Theory , also known as the Three-Needs Theory, was developed by David McClelland in the 1960s and identifies three primary motivators in people: the need for achievement, affiliation, and power. According to McClelland, every individual has a combination of these three needs, but one usually dominates and influences behavior. The need for achievement (nAch) is the drive to excel, achieve goals, and succeed. People high in nAch prefer challenging tasks and personal responsibility. The need for affiliation (nAff) is the desire for friendly relationships and social approval. Such individuals value teamwork and harmony. The need for power (nPow) is the desire to influence, lead, and control others. High nPow individuals are effective in leadership roles. Unlike Maslow’s hierarchy, McClelland’s theory suggests these needs are learned and can be developed through training.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3a9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'mcclelland-s-needs-theory-b-leadership-meaning' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3a9-en-675","language":"English","title":"importance' || char(59) || ' Leadership theory: Great Man","topic_slug":"importance-leadership-theory-great-man","definition":"Great Man Theory of Leadership is one of the earliest leadership theories, suggesting that great leaders are born with inherent qualities and destined to lead during times of crisis. Proposed in the 19th century, this theory assumes that leadership is an innate ability and that only a few exceptional individuals possess the natural traits to become great leaders. It was based on the study of historical figures like Napoleon, Gandhi, and Churchill, who emerged as leaders during critical periods. The theory implies that leadership cannot be taught or developed—it is inborn. While it emphasizes charisma and heroic qualities, it lacks scientific evidence and ignores situational factors. It also fails to explain how leadership can be developed in ordinary individuals. Despite its limitations, the theory laid the foundation for later leadership studies by focusing on personal attributes.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3a9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'importance-leadership-theory-great-man' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3a9-en-676","language":"English","title":"Trait","topic_slug":"trait","definition":"Trait Theory of Leadership proposes that effective leaders possess certain inherent personality traits that distinguish them from non-leaders. Developed in the early 20th century, this theory focuses on identifying the personal characteristics—such as intelligence, self-confidence, determination, integrity, and sociability—that contribute to leadership success. Researchers attempted to isolate a universal set of traits common to successful leaders across situations. While some traits like confidence and decisiveness are frequently associated with leadership, the theory fails to explain why some people with these traits do not become effective leaders. It also overlooks the role of environment, experience, and skills. Nevertheless, trait theory contributed to leadership assessment and selection processes. Modern leadership development still considers traits as one component, though not the sole determinant of success.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3a9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'trait' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3a9-en-677","language":"English","title":"Situational","topic_slug":"situational","definition":"Situational Leadership Theory , developed by Paul Hersey and Ken Blanchard in the 1970s, asserts that effective leadership depends on the situation and the maturity level of followers. According to this theory, there is no single best leadership style' || char(59) || ' instead, leaders must adapt their style based on the readiness of subordinates to perform a task. Readiness is determined by the follower’s ability and willingness. The model identifies four leadership styles: Telling (S1) for low readiness, Selling (S2) for moderate readiness, Participating (S3) for moderate to high readiness, and Delegating (S4) for high readiness. Leaders must diagnose the situation and adjust their behavior accordingly. This theory emphasizes flexibility and responsiveness. It is widely used in training programs because it provides a practical framework for real-world leadership challenges.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3a9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'situational' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3a9-en-678","language":"English","title":"Behavioural","topic_slug":"behavioural","definition":"Behavioural Theory of Leadership focuses on the actions and behaviors of leaders rather than their innate traits, suggesting that leadership can be learned through observation and training. Emerging in the 1940s and 1950s, this theory shifts focus from \"what leaders are\" to \"what leaders do.\" It is based on research conducted at Ohio State University and the University of Michigan. Ohio State identified two key dimensions: initiating structure (task-oriented behavior) and consideration (people-oriented behavior). The University of Michigan found similar dimensions: employee-oriented and production-oriented leadership. Effective leaders balance both task and relationship behaviors. Unlike trait theory, this approach supports leadership development through training and feedback. It laid the foundation for modern leadership styles and management practices.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3a9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'behavioural' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3a9-en-679","language":"English","title":"Blake and Mouton''s Managerial Grid theory","topic_slug":"blake-and-mouton-s-managerial-grid-theory","definition":"Blake and Mouton''s Managerial Grid Theory , developed in 1964, is a leadership model that maps leadership styles on a grid based on concern for production and concern for people. Robert Blake and Jane Mouton proposed a two-dimensional model where the x-axis represents concern for production (task orientation) and the y-axis represents concern for people (relationship orientation), each rated from 1 (low) to 9 (high). The grid identifies five leadership styles: Impoverished (1,1) , Country Club (1,9) , Authority-Compliance (9,1) , Middle-of-the-Road (5,5) , and Team Management (9,9) . The Team Management style, which scores high on both dimensions, is considered the most effective as it fosters high productivity through teamwork and trust. The model helps managers assess their leadership style and strive for optimal balance. It is widely used in leadership training and organizational development.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3a9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'blake-and-mouton-s-managerial-grid-theory' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3a9-en-680","language":"English","title":"Transactional vs Transformational leadership.","topic_slug":"transactional-vs-transformational-leadership","definition":"Transactional and Transformational Leadership are two contrasting leadership approaches introduced by James MacGregor Burns and later expanded by Bernard Bass. Transactional leadership is based on exchanges between leaders and followers, where rewards and punishments are used to achieve compliance and meet established goals. Leaders clarify roles, set expectations, and provide feedback based on performance. It works well in stable environments with routine tasks. In contrast, transformational leadership inspires and motivates followers to exceed expectations and achieve higher levels of performance. Transformational leaders provide vision, stimulate intellect, offer individualized consideration, and act as role models (idealized influence). They foster innovation, change, and long-term growth. While transactional leadership maintains the status quo, transformational leadership drives organizational change. Bernard Bass integrated both models, suggesting effective leaders use a combination depending on the context.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3a9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'transactional-vs-transformational-leadership' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de398-en-681","language":"English","title":"Indian Ethos in Management","topic_slug":"indian-ethos-in-management","definition":"Indian Ethos in Management refers to the application of values, beliefs, and principles derived from India’s ancient cultural and spiritual traditions to modern managerial practices. It emphasizes harmony, duty, ethical conduct, and holistic well-being in organizational life. Indian ethos in management draws from a rich legacy of philosophical and religious texts such as the Vedas, Upanishads, Puranas, and epics like the Ramayana and Mahabharata. These scriptures promote values such as truth (Satya), non-violence (Ahimsa), self-discipline, and righteous action (Dharma), which are integral to ethical leadership and sustainable management. The concept encourages managers to balance material success with moral responsibility, fostering long-term organizational health. It supports decision-making rooted in conscience and collective welfare rather than mere profit maximization. The Vedic vision of Vasudhaiva Kutumbakam (\"the world is one family\") promotes global corporate citizenship and inclusive growth. This ethos also emphasizes inner development through meditation and mindfulness for better managerial effectiveness.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de398' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'indian-ethos-in-management' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de398-en-682","language":"English","title":"Bhagavad Gita","topic_slug":"bhagavad-gita","definition":"The Bhagavad Gita is a 700-verse Hindu scripture that is part of the Indian epic Mahabharata, set in the context of the Kurukshetra War, where Lord Krishna imparts spiritual and ethical guidance to Prince Arjuna. It serves as a guide to righteous action and leadership, offering profound insights applicable to modern management. The Gita teaches the philosophy of Nishkama Karma, or selfless action—performing one’s duties without attachment to results—making it highly relevant for stress-free and ethical management. It emphasizes leadership with equanimity, as Krishna advises Arjuna to maintain balance in success and failure, a key trait for managers facing uncertainty. The concept of Swadharma highlights the importance of fulfilling one’s role and responsibilities according to one’s nature and position. Managers are encouraged to lead with wisdom, emotional intelligence, and detachment, ensuring clarity in decision-making.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de398' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'bhagavad-gita' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de398-en-683","language":"English","title":"Management lessons from Kautilya''s Arthashastra - an overview only","topic_slug":"management-lessons-from-kautilya-s-arthashastra-an-overview-only","definition":"Kautilya’s Arthashastra is an ancient Indian treatise on statecraft, economic policy, and military strategy, written in Sanskrit during the 4th century BCE by Chanakya (also known as Vishnugupta or Kautilya), the advisor to Emperor Chandragupta Maurya. Though primarily a political text, it offers valuable insights into administration, governance, and organizational management. The Arthashastra emphasizes efficient administration, structured hierarchy, and accountability—principles that are directly applicable to modern organizational management. It outlines the duties of a king (leader) as protector, administrator, and moral guide, paralleling the responsibilities of a CEO or manager. The text advocates for a strong system of checks and balances, including espionage and audits, to prevent corruption and ensure transparency. It discusses resource management, taxation, labor relations, and public welfare, reflecting a holistic approach to governance.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de398' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'management-lessons-from-kautilya-s-arthashastra-an-overview-only' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de398-en-684","language":"English","title":"Ethics vs Ethos","topic_slug":"ethics-vs-ethos","definition":"Ethics refers to a set of moral principles that govern an individual’s or group’s behavior, while Ethos denotes the underlying values, beliefs, and cultural character of a society or organization that shape behavior over time. While ethics are often codified and universal, ethos is more contextual and deeply embedded in tradition. Ethics involves rules and standards that define right and wrong conduct, such as honesty, fairness, and integrity, and are often formalized in codes of conduct or laws. Ethos, on the other hand, reflects the collective mindset and cultural identity that influence how ethical principles are interpreted and practiced in a particular setting. For example, Indian ethos emphasizes Dharma, duty, and spiritual growth, which inform ethical behavior in a culturally specific way. Ethics can be taught and enforced, but ethos is absorbed through socialization, tradition, and shared values.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de398' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'ethics-vs-ethos' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35b-en-685","language":"English","title":"Exam Tip","topic_slug":"exam-tip","definition":"This topic is commonly asked in short answer questions (2–5 marks) . Students often lose marks by failing to mention the 12-month rule or confusing tourists with migrants. Always cite the UNWTO definition and include the Ministry of Tourism, 1967 for full credit.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'exam-tip' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de367-en-686","language":"English","title":"Travel Agencies","topic_slug":"travel-agencies","definition":"These are physical or online businesses that sell travel products. Traditional travel agencies operate from storefronts and offer personalized service. Online Travel Agencies (OTAs) like MakeMyTrip , Goibibo , and Yatra.com dominate the digital space, allowing users to compare prices and book instantly.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de367' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'travel-agencies' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de367-en-687","language":"English","title":"Meta-Search Engines","topic_slug":"meta-search-engines","definition":"Platforms like Google Flights , Kayak , and Skyscanner do not sell directly but compare prices across multiple OTAs and airlines, helping consumers find the best deals. In Assam, local travel intermediaries such as Assam Travels and Brahmaputra Travel Agency offer customized packages to Kaziranga, Manas, and Tawang. They collaborate with homestays and jeep operators, demonstrating the multiplier effect of tourism. The rise of direct booking through airline and hotel websites has challenged traditional intermediaries, but OTAs remain dominant due to convenience and bundled offers.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de367' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'meta-search-engines' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de367-en-688","language":"English","title":"Classification of Accommodation","topic_slug":"classification-of-accommodation","definition":"Hotels – Classified by star ratings (1 to 5 stars) based on facilities, service quality, and amenities. In India, the Ministry of Tourism conducts star certification. Five-star hotels like ITC Sonar, Kolkata or Radisson Blu, Guwahati offer luxury services, while budget hotels cater to cost-conscious travelers. 2. Resorts – Located in scenic areas (hill stations, beaches, forests), resorts offer recreational facilities like spas, swimming pools, and adventure activities. Kaziranga Resort and Diphu Hill Resort are examples in Assam. 3. Homestays – Private homes where tourists stay with local families, offering cultural immersion. The Assam Homestay Policy (2017) promotes this model in villages like Majuli and Sualkuchi , supporting rural livelihoods. 4. Lodges and Guesthouses – Smaller, independently run establishments offering basic amenities. Common in pilgrimage and hill stations. 5. Hostels – Budget accommodations, often targeting backpackers and youth. Zostel operates in key Indian cities and tourist spots. 6.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de367' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'classification-of-accommodation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de367-en-689","language":"English","title":"Air Transport","topic_slug":"air-transport","definition":"The fastest mode, ideal for long-distance and international travel. Air India , IndiGo , and SpiceJet connect major Indian cities to Assam. Lokpriya Gopinath Bordoloi International Airport (Guwahati) is the region’s aviation hub. Air travel reduces journey time but is costlier and has environmental impacts.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de367' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'air-transport' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de367-en-690","language":"English","title":"Rail Transport","topic_slug":"rail-transport","definition":"Operated by Indian Railways , it is the most affordable and widely used mode for domestic tourism. The Vande Bharat Express and Rajdhani Express offer comfort and speed. In Assam, the Brahmaputra Mail and Kaziranga Express connect key towns. Rail tourism includes luxury trains like Maharajas’ Express .","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de367' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'rail-transport' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de367-en-691","language":"English","title":"Water Transport","topic_slug":"water-transport","definition":"Used for river cruises and island access. The Brahmaputra River Cruise from Guwahati to Dibrugarh offers tourism experiences. Inland Waterways Authority of India (IWAI) develops National Waterway 2 (Brahmaputra), boosting cruise tourism. Transport infrastructure affects destination choice —poor roads deter tourists. The Bharatmala and Sagarmala projects aim to improve connectivity. In Assam, the Trans-Arunachal Highway and Bogibeel Bridge enhance regional access. Sustainable transport, like electric buses and non-motorized boats , is being promoted to reduce carbon footprint.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de367' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'water-transport' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de396-en-692","language":"English","title":"Economic Impact","topic_slug":"economic-impact","definition":"Tourism is a major source of foreign exchange earnings , employment generation , and infrastructure development . It contributes to GDP and stimulates growth in related sectors like transport, hospitality, and handicrafts. In Assam, tourism supports livelihoods in tea gardens, river cruises, and handloom industries. However, economic leakage —where a significant portion of tourism income leaves the local economy (e.g., through foreign-owned hotels or imported goods)—reduces benefits. Seasonality also causes income instability, as seen in Kaziranga, where tourism peaks during winter. Additionally, inflation in local prices (e.g., food, rent) can negatively affect residents.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de396' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'economic-impact' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de396-en-693","language":"English","title":"Socio-Cultural Impact","topic_slug":"socio-cultural-impact","definition":"On the positive side, tourism fosters cultural exchange , revival of traditions , and community pride . Festivals like Bihu in Assam gain national attention due to tourist interest. However, negative effects include cultural commodification , where traditions are altered for tourist consumption (e.g., staged Bihu dances). Demonstration effect —where locals imitate tourist lifestyles—can erode traditional values. Social disruption may occur due to increased crime, prostitution, or substance abuse in tourist hotspots. Moreover, land alienation —displacement of locals for tourism projects—is a growing concern in ecologically sensitive areas.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de396' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'socio-cultural-impact' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de396-en-694","language":"English","title":"Environmental Impact","topic_slug":"environmental-impact","definition":"Tourism can lead to habitat destruction , pollution , deforestation , and biodiversity loss . In Kaziranga National Park, increased vehicle traffic and littering threaten rhino habitats. Water scarcity is another issue, as hotels consume large quantities of water in areas where locals face shortages. Conversely, tourism can fund conservation efforts —entry fees from tourists help maintain national parks. Eco-tourism initiatives, like those in Nameri National Park , promote environmental awareness and fund anti-poaching units. The Butler’s Tourism Area Life Cycle (TALC) Model (1980) explains how destinations evolve from exploration to decline, with impacts intensifying over time. Early stages bring economic benefits' || char(59) || ' later stages often result in environmental degradation and resident resentment.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de396' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'environmental-impact' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35d-en-695","language":"English","title":"Texts Carl Sagan : Growing up with Science Fiction","topic_slug":"texts-carl-sagan-growing-up-with-science-fiction","definition":"Texts Carl Sagan : Growing up with Science Fiction refers to the essay by renowned astrophysicist Carl Sagan that explores how early exposure to science fiction shaped his scientific imagination and career. In this reflective non-fiction piece, Sagan discusses how reading science fiction during his childhood sparked curiosity about space, technology, and the future. He emphasizes that while these stories were imaginative, they also planted seeds for real scientific inquiry and innovation. Sagan acknowledges writers like H.G. Wells and Arthur C. Clarke as influences who blended scientific plausibility with narrative creativity. The essay highlights the educational value of speculative literature in inspiring young minds toward STEM fields. It also underscores the role of literature in shaping worldviews and fostering critical thinking. This text is particularly significant in English Communication-II (AEC – Semester 4) for demonstrating how personal narrative can convey intellectual development.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35d' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'texts-carl-sagan-growing-up-with-science-fiction' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35d-en-696","language":"English","title":"Shirley Jackson : The Lottery","topic_slug":"shirley-jackson-the-lottery","definition":"Shirley Jackson : The Lottery refers to the 1948 short story by American author Shirley Jackson that critiques blind adherence to tradition through a shocking village ritual. Set in a small rural village, The Lottery describes an annual event where one resident is randomly selected and stoned to death by the community. The narrative unfolds with a deceptively calm tone, gradually revealing the horror of the tradition. Jackson uses irony and understatement to highlight how people accept violence when it is normalized by custom. The story sparked widespread controversy upon publication due to its disturbing theme and unexpected ending. It is a key text in English Communication-II (AEC – Semester 4) for teaching thematic analysis, character and setting, and literary devices such as foreshadowing and symbolism. The work remains a powerful example of social critique in American literature.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35d' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'shirley-jackson-the-lottery' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35d-en-697","language":"English","title":"A.G Gardiner : On Saying Please","topic_slug":"a-g-gardiner-on-saying-please","definition":"A.G Gardiner : On Saying Please refers to the essay by Arthur Gordon Gardiner that emphasizes the importance of courtesy and small acts of politeness in civil society. In On Saying Please , Gardiner recounts a personal anecdote about using the lift in a building where the operator refused to respond to polite requests. Through this incident, he reflects on the value of simple courtesies like saying “please” and “thank you” in maintaining social harmony. He argues that such expressions are not mere formalities but essential tools for mutual respect and emotional well-being. Gardiner’s style combines gentle humor with moral insight, making his essay accessible and thought-provoking. The text is used in English Communication-II (AEC – Semester 4) to explore tone, argumentation, and ethical reflection in prose. It also serves as a model for clear, persuasive non-fiction writing.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35d' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'a-g-gardiner-on-saying-please' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35d-en-698","language":"English","title":"Comprehension","topic_slug":"comprehension","definition":"Comprehension is the ability to understand, interpret, and retain the meaning of a written text. It involves not only grasping the literal content but also recognizing implied ideas, purpose, and structure. In English Communication-II (AEC – Semester 4), comprehension skills are developed through exercises that test recall, inference, and summarization of the prescribed texts. Students must be able to answer questions about main ideas, supporting details, sequence of events, and author’s intent. Effective comprehension requires active reading strategies such as questioning, predicting, and connecting ideas. It is a foundational skill for all other literary tasks, including analysis, paraphrasing, and vocabulary building. Strong comprehension enables students to engage meaningfully with diverse texts like Sagan’s reflective essay or Jackson’s symbolic narrative.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35d' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'comprehension' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35d-en-699","language":"English","title":"Analysis and interpretation","topic_slug":"analysis-and-interpretation","definition":"Analysis and interpretation involves breaking down a text into its components and explaining their significance to derive deeper meaning. Analysis focuses on identifying elements such as theme, character, setting, plot, and literary devices, while interpretation explains what these elements suggest about human experience or societal values. In English Communication-II (AEC – Semester 4), students analyze texts like The Lottery for thematic analysis , examine character and setting in relation to plot development, and identify literary devices such as irony, symbolism, and foreshadowing. Interpretation requires students to go beyond summary and offer reasoned insights supported by textual evidence. This skill is crucial for writing critical responses and essays. Both analysis and interpretation foster higher-order thinking and enable students to appreciate the complexity of literary works.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35d' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'analysis-and-interpretation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35d-en-700","language":"English","title":"Paraphrasing","topic_slug":"paraphrasing","definition":"Paraphrasing is the act of restating a text in one’s own words while preserving the original meaning and intent. It requires understanding the source material thoroughly and expressing it clearly and accurately without copying the exact phrasing. In English Communication-II (AEC – Semester 4), paraphrasing is used to demonstrate comprehension and avoid plagiarism. Students practice paraphrasing sentences, paragraphs, and key arguments from texts like Sagan’s essay or Gardiner’s reflections. Effective paraphrasing involves changing sentence structure, using synonyms, and maintaining logical flow. It is a vital skill for summarizing, note-taking, and academic writing. Unlike summarizing, paraphrasing retains the same level of detail as the original, just in different words.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35d' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'paraphrasing' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35d-en-701","language":"English","title":"Vocabulary building","topic_slug":"vocabulary-building","definition":"Vocabulary building is the process of expanding one’s range of words and understanding their meanings, usage, and context. It involves learning new words from reading materials and mastering their spelling, pronunciation, synonyms, antonyms, and grammatical functions. In English Communication-II (AEC – Semester 4), students enhance their vocabulary by studying key terms from the prescribed texts—such as “superstition” in The Lottery or “civility” in On Saying Please . Context clues, word roots, and collocations are used to infer and retain meanings. A strong vocabulary improves reading comprehension, writing clarity, and spoken expression. Regular practice through flashcards, word lists, and usage in sentences helps internalize new terms.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35d' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'vocabulary-building' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de35d-en-702","language":"English","title":"Scanning and Skimming","topic_slug":"scanning-and-skimming","definition":"Scanning and Skimming are rapid reading techniques used to locate specific information or grasp the main idea of a text quickly. Skimming involves reading quickly to get an overview of the content, focusing on titles, headings, topic sentences, and conclusions. It is useful for previewing a text or identifying its general theme. Scanning , on the other hand, is used to find particular details such as names, dates, or keywords without reading the entire passage. In English Communication-II (AEC – Semester 4), these skills help students manage time during exams and efficiently extract information from literary and non-literary texts. Both techniques are essential for academic reading, research, and answering objective-type questions. Mastery of scanning and skimming improves reading efficiency without compromising understanding.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de35d' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'scanning-and-skimming' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37d-en-703","language":"English","title":"Grammar and punctuation","topic_slug":"grammar-and-punctuation","definition":"Grammar and punctuation are foundational elements of written language that govern the structure of sentences and the clarity of meaning. Grammar refers to the set of structural rules governing the composition of words, phrases, and sentences in a language, while punctuation involves the use of standardized symbols to organize written text and clarify meaning. Proper grammar ensures that sentences are syntactically correct and semantically clear, enabling effective communication. It includes rules for subject-verb agreement, tense consistency, correct use of parts of speech, and sentence formation. Punctuation marks such as periods, commas, question marks, quotation marks, and colons help indicate pauses, intonation, and structural relationships within sentences. Without correct punctuation, even grammatically sound sentences can be ambiguous or misleading. Together, grammar and punctuation enhance readability, professionalism, and precision in all forms of writing. Mastery of these elements is essential for academic writing, official correspondence, and digital communication.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37d' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'grammar-and-punctuation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37d-en-704","language":"English","title":"generating ideas","topic_slug":"generating-ideas","definition":"Generating ideas is the cognitive process of brainstorming and organizing thoughts before beginning to write, ensuring content is relevant, original, and well-structured. It is a crucial pre-writing stage that helps writers explore topics, identify key points, and determine the purpose and audience of their writing. Effective idea generation allows writers to overcome blank-page anxiety and develop a clear direction for their work. Techniques such as mind mapping, freewriting, listing, and questioning (5Ws and 1H) stimulate creative and critical thinking. This process is especially important in forms like report writing, letters to the editor, and presentations, where clarity of argument and logical flow are essential. Ideas must be evaluated for relevance, feasibility, and coherence before being developed into full sentences or paragraphs. In collaborative settings like meetings, idea generation contributes to agenda setting and problem-solving. It fosters innovation and ensures comprehensive coverage of a topic.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37d' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'generating-ideas' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37d-en-705","language":"English","title":"building sentences and paragraph","topic_slug":"building-sentences-and-paragraph","definition":"Building sentences and paragraph refers to the process of constructing grammatically correct, meaningful sentences and organizing them into coherent, unified paragraphs that convey a central idea. A sentence expresses a complete thought, while a paragraph develops a single point through a group of related sentences. Effective sentence construction involves using proper syntax, appropriate vocabulary, and correct punctuation to ensure clarity and variety. Simple, compound, complex, and compound-complex sentences allow writers to vary rhythm and express relationships between ideas. A well-developed paragraph begins with a topic sentence , followed by supporting sentences that provide explanations, examples, or evidence, and often ends with a concluding sentence . Unity, coherence, and logical progression are essential for readability. Transitions such as “however,” “furthermore,” and “in addition” link ideas within and between sentences. This skill is vital in all writing forms, from reports to letters and presentations.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37d' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'building-sentences-and-paragraph' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37d-en-706","language":"English","title":"Report writing","topic_slug":"report-writing","definition":"Report writing (including newspaper report) is a formal style of writing that presents information in an organized, factual, and objective manner for a specific audience and purpose. A newspaper report is a type of journalistic writing that informs the public about current events using the inverted pyramid structure. Reports are structured into sections such as title, introduction, methodology, findings, conclusion, and recommendations. They must be clear, concise, and based on evidence. Newspaper reports follow the 5W1H format (Who, What, When, Where, Why, How) and prioritize the most important information at the beginning. Headlines are attention-grabbing and summarize the main event. Language is neutral, factual, and free from personal opinion. Visual elements like photographs or quotes may be included to enhance credibility and engagement. Report writing is used in academic, administrative, and media contexts.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37d' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'report-writing' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37d-en-707","language":"English","title":"Letter writing","topic_slug":"letter-writing","definition":"Letter writing (applications and Letters to the Editor) involves composing formal written communication for specific purposes— applications seek jobs, admissions, or permissions, while Letters to the Editor express opinions on public issues in newspapers. Both forms follow a structured format and require clarity, politeness, and correctness. Application letters, also known as cover letters, accompany resumes and highlight qualifications, experience, and suitability for a position. They include sender’s address, date, salutation, subject, body, closing, and signature. Letters to the Editor are published in newspapers to engage in public discourse, critique policies, or appreciate initiatives. They must be concise, relevant, and respectful. Both types demand proper grammar, punctuation, and formal tone. These letters reflect the writer’s communication skills and professionalism.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37d' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'letter-writing' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37d-en-708","language":"English","title":"Memos and Circulars","topic_slug":"memos-and-circulars","definition":"Memos and Circulars are internal and external organizational documents used to disseminate information, instructions, or announcements within or across institutions. A memo (memorandum) is typically used for internal communication, while a circular is sent to a wider audience, often outside the organization. Memos are concise, direct, and structured with headings such as To , From , Date , and Subject . They are used for policy updates, meeting reminders, or procedural changes. Circulars are more formal and may be printed or emailed to multiple recipients to announce events, holidays, or new rules. Both documents emphasize clarity and brevity. Unlike letters, they do not require salutations or complimentary closes. They play a key role in administrative efficiency and information flow in offices, colleges, and government departments.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37d' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'memos-and-circulars' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37d-en-709","language":"English","title":"Agendas and Minutes","topic_slug":"agendas-and-minutes","definition":"Agendas and Minutes are official documents used in meetings to plan discussions and record outcomes. The agenda is a pre-meeting document listing topics to be discussed, while the minutes are a post-meeting summary of decisions, actions, and discussions. The agenda helps participants prepare and ensures the meeting stays focused. It includes meeting title, date, time, venue, and numbered items with time allocations. Minutes are written in formal, neutral language and include the meeting’s name, date, attendees, key points discussed, decisions made, and action items with responsible persons and deadlines. The secretary usually prepares minutes. They serve as legal records and reference documents. Accuracy and clarity are crucial, as minutes may be reviewed by absent members or auditors.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37d' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'agendas-and-minutes' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87812c1a19d2142de37d-en-710","language":"English","title":"PowerPoint Presentation","topic_slug":"powerpoint-presentation","definition":"PowerPoint Presentation is a digital slide-based format used to visually support oral presentations in academic, professional, and public settings. It combines text, images, charts, and animations to convey information clearly and engagingly. Each slide should focus on one key idea, using bullet points, headings, and visuals to enhance understanding. Slides must be concise—avoiding long paragraphs—and use readable fonts and contrasting colors. The presenter speaks to elaborate on points, while slides serve as visual aids. A typical structure includes a title slide, agenda, content slides, summary, and Q&A slide. Effective presentations are well-organized, audience-appropriate, and technically sound. They are widely used in classrooms, boardrooms, and conferences.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87812c1a19d2142de37d' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'powerpoint-presentation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
